-- ----------------------------
-- Table structure for biz_case
-- ----------------------------
DROP TABLE IF EXISTS `biz_case`;
CREATE TABLE `biz_case`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自编字段，表主键，自增ID',
  `status` int NOT NULL COMMENT '案件状态，关联biz_case_status_dict字典表，如待受理-0/办理中-1/已办结-2/已驳回-3',
  `type` int NOT NULL COMMENT '案件类型，0=食药案件,1=质量案件',
  `case_no` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '案件编号，唯一标识',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间，自动记录创建时间',
  `accept_time` datetime NULL DEFAULT NULL COMMENT '受理时间，可为空',
  `complete_time` datetime NULL DEFAULT NULL COMMENT '办结完成时间，可为空',
  `region_full_code` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '案件所属地区 fullCode，支持6位或12位，用于地图展示和筛选',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '市场监管案件表' ROW_FORMAT = DYNAMIC;

