-- ----------------------------
-- Table structure for biz_cross_region_dispatch
-- ----------------------------
DROP TABLE IF EXISTS `biz_cross_region_dispatch`;
CREATE TABLE `biz_cross_region_dispatch`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增主键ID',
  `coordinate_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '协调ID，唯一编码，UUID生成',
  `coordinate_no` char(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '协调编号，系统自动生成，格式“CROSS_DISP+年份（4位）+6位流水号”',
  `apply_unit_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '申请单位ID，发起申请的本地联动单位ID，关联联动单位信息表（biz_coop_unit_info）',
  `apply_unit_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '申请单位名称，与申请单位ID同步，关联联动单位信息表（biz_coop_unit_info）',
  `cooper_unit_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '协作单位ID，跨域协作单位ID，关联联动单位信息表（biz_coop_unit_info）',
  `cooper_unit_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '协作单位名称，与协作单位ID同步，关联联动单位信息表（biz_coop_unit_info）',
  `apply_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '申请理由，如“XX市遭遇特大洪涝，本地冲锋舟仅3辆，需邻市支援5辆”',
  `res_type` char(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '所需资源类型，应急物资/救援队伍/救援车辆/救援设备',
  `res_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '所需资源名称，如“冲锋舟”“专业抗洪队伍”',
  `require_quantity` int NOT NULL COMMENT '所需数量，资源需求数量',
  `cooper_region` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '协作区域，如“XX市XX区”，关联行政区划表（sys_area）',
  `apply_status` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '待审核' COMMENT '申请状态，待审核/已通过/已驳回，默认待审核',
  `apply_user_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '申请人ID，申请管理员账号，关联用户信息表（sys_user）',
  `apply_user_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '申请人姓名，与申请人ID同步，关联用户信息表（sys_user）',
  `apply_time` datetime NOT NULL COMMENT '申请时间，格式yyyy-MM-dd HH:mm:ss，系统自动生成',
  `audit_user_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '审核人ID，协作单位审核人账号，审核后必填，关联用户信息表（sys_user）',
  `audit_user_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '审核人姓名，与审核人ID同步，关联用户信息表（sys_user）',
  `audit_time` datetime NULL DEFAULT NULL COMMENT '审核时间，格式yyyy-MM-dd HH:mm:ss，审核后必填',
  `audit_opinion` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '审核意见，审核反馈，如“同意支援5辆冲锋舟，24小时内到位”',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分类扩展字段1，预留，如“协调优先级”',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分类扩展字段2，预留，如“协调优先级”',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '通用扩展字段1，预留，存储协作协议路径',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '通用扩展字段2，预留，存储协作协议路径',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '跨域调度协调表' ROW_FORMAT = DYNAMIC;

