-- ----------------------------
-- Table structure for biz_decision_effect_eval
-- ----------------------------
DROP TABLE IF EXISTS `biz_decision_effect_eval`;
CREATE TABLE `biz_decision_effect_eval`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `effect_eval_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '评估ID，唯一编码，UUID生成',
  `rel_scheme_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联方案ID，关联决策方案表的方案ID，决策方案表（biz_decision_scheme）',
  `rel_scheme_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联方案名称，与方案ID同步，决策方案表（biz_decision_scheme）',
  `implementation_cycle` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '实施周期，实际实施周期（如“2025-10-01至2025-12-20”），决策执行跟踪表（biz_decision_exec_track）',
  `expected_effect` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '预期效果，方案预期效果（如“事件下降50%”），决策方案表（biz_decision_scheme）',
  `actual_effect` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '实际效果，最终实际效果（如“事件下降55%”），分域分析统计表（如stat_analysis_mon_evt）',
  `effect_achievement_rate` decimal(5, 2) NOT NULL COMMENT '效果达成率，实际效果/预期效果×100，取值范围：0.00-100.00，单位：%，无',
  `resource_total_input` decimal(10, 2) NOT NULL COMMENT '资源总投入，实施过程中资源投入总额（设备+人员+其他），单位：万元，资源投入表（biz_res_input）',
  `input_return_rate` decimal(10, 2) NULL DEFAULT NULL COMMENT '投入回报率，(实际收益-资源投入)/资源投入×100，取值范围：-100.00-1000.00，单位：%，无',
  `user_satisfy` decimal(5, 2) NULL DEFAULT NULL COMMENT '用户满意度，用户满意度调查结果，取值范围：0.00-100.00，单位：%，用户满意度调查表（biz_user_satisfy_survey）',
  `eval_grade` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '评估等级：优秀/良好/合格/不合格，判定规则：效果达成率≥120%=优秀，100%-119%=良好，80%-99%=合格，<80%=不合格，无',
  `success_exp` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '成功经验，方案实施中的成功做法（如“传感器部署覆盖重点区域”），无',
  `improve_pts` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '改进点，需优化的问题（如“人员应急处置培训不足”），无',
  `eval_user` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '评估人，负责评估的用户ID，用户信息表（sys_user）',
  `eval_time` datetime NOT NULL COMMENT '评估时间，格式：yyyy-MM-dd HH:mm:ss',
  `eval_rpt_attach` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '评估报告附件，评估报告文件路径（PDF格式），无',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段1，预留，如“评估类型”',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段2，预留，如“评估类型”',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段1，预留，存储评估会议纪要链接',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段2，预留，存储评估会议纪要链接',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 16 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '决策效果评估表' ROW_FORMAT = DYNAMIC;

