-- ----------------------------
-- Table structure for biz_decision_exec_track
-- ----------------------------
DROP TABLE IF EXISTS `biz_decision_exec_track`;
CREATE TABLE `biz_decision_exec_track`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `exec_track_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '跟踪ID，唯一编码，UUID生成',
  `rel_scheme_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联方案ID，关联决策方案表的方案ID，决策方案表（biz_decision_scheme）',
  `rel_scheme_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联方案名称，与方案ID同步，决策方案表（biz_decision_scheme）',
  `planned_exec_cycle` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '计划实施周期，如“2025-10-01至2025-12-31”，决策方案表（biz_decision_scheme）',
  `executed_days` int NOT NULL COMMENT '已实施天数，天，当前日期-实施启动日期',
  `exec_progress` decimal(5, 2) NOT NULL COMMENT '实施进度，%，0.00-100.00，已完成任务数/计划任务数×100，执行进度记录表（biz_exec_progress_rec）',
  `expected_effect_idx` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '预期效果指标，如“燃气泄漏事件下降50%，响应时长≤20分钟”，决策方案表（biz_decision_scheme）',
  `actual_effect_idx` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '实际效果指标，如“燃气泄漏事件下降40%，响应时长≤25分钟”，分域分析统计表（如stat_analysis_mon_evt）',
  `effect_achievement_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '效果达成率，%，0.00-100.00，实际效果/预期效果×100（多指标取平均值）',
  `unmet_items` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '未达标项，如“事件下降率未达预期（40%<50%）\"',
  `track_status` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '跟踪状态，实施中/已完成/逾期未完成，标识跟踪状态',
  `track_user` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '跟踪人，负责跟踪的用户ID，用户信息表（sys_user）',
  `track_time` datetime NOT NULL COMMENT '跟踪时间，格式：yyyy-MM-dd HH:mm:ss',
  `last_track_time` datetime NULL DEFAULT NULL COMMENT '上次跟踪时间，格式：yyyy-MM-dd HH:mm:ss，记录上次跟踪时间',
  `rectification_sugg` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '整改建议，针对未达标项的建议（如“加强专项小组巡检频次”）',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段1，预留，如“跟踪频次”',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段2，预留，如“跟踪频次”',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段1，预留，存储实施负责人联系方式',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段2，预留，存储实施负责人联系方式',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '决策执行跟踪表' ROW_FORMAT = DYNAMIC;

