-- ----------------------------
-- Table structure for biz_decision_opt_sugg
-- ----------------------------
DROP TABLE IF EXISTS `biz_decision_opt_sugg`;
CREATE TABLE `biz_decision_opt_sugg`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `opt_sugg_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '建议ID，唯一编码，UUID生成',
  `rel_eval_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联评估ID，关联决策效果评估表的评估ID，决策效果评估表（biz_decision_effect_eval）',
  `rel_scheme_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联方案ID，关联决策方案表的方案ID，决策方案表（biz_decision_scheme）',
  `rel_scheme_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联方案名称，与方案ID同步，决策方案表（biz_decision_scheme）',
  `sugg_type` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '建议类型：系统自动/手动补充，标识建议来源',
  `sugg_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '建议内容，优化建议详情（如“增加每月2次应急培训”）',
  `ref_case_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '参考案例ID，关联典型场景案例库表的案例ID（系统自动建议时必填），典型场景案例库表（biz_typical_scenario_case）',
  `ref_case_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '参考案例名称，与案例ID同步，典型场景案例库表（biz_typical_scenario_case）',
  `sugg_priority` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '建议优先级：高/中/低，建议实施优先级',
  `sugg_status` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '建议状态：待采纳/已采纳/已驳回，标识建议处理状态',
  `proposer` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '提出人，建议提出人ID（系统自动建议为“sys”），用户信息表（sys_user）',
  `proposer_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '提出人姓名，与提出人同步，用户信息表（sys_user）',
  `propose_time` datetime NOT NULL COMMENT '提出时间，格式：yyyy-MM-dd HH:mm:ss',
  `handler` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '处理人，处理建议的用户ID，用户信息表（sys_user）',
  `handle_time` datetime NULL DEFAULT NULL COMMENT '处理时间，格式：yyyy-MM-dd HH:mm:ss，建议状态非“待采纳”时必填',
  `handle_opinion` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '处理意见，处理建议的理由（如“采纳，下月起执行培训”）',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段1，预留，如“建议适用场景”',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段2，预留，如“建议适用场景”',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段1，预留，存储建议实施计划',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段2，预留，存储建议实施计划',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 20 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '决策优化建议表' ROW_FORMAT = DYNAMIC;

