-- ----------------------------
-- Table structure for biz_decision_scheme
-- ----------------------------
DROP TABLE IF EXISTS `biz_decision_scheme`;
CREATE TABLE `biz_decision_scheme`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `decision_scheme_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '方案ID，唯一编码，UUID生成',
  `scheme_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '方案名称，如“XX区域燃气泄漏事件处置优化方案”',
  `rel_analysis_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联分析ID，关联分域分析统计ID，分域分析统计表（如stat_analysis_mon_evt）',
  `rel_analysis_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联分析类型，按行政区划/按监测事件/按设备，标识关联分析的分域类型',
  `scheme_goal` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '方案目标，如“3个月内该区域燃气泄漏事件下降50%”',
  `implementation_measures` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '实施措施，分点描述措施（如“1.新增3个传感器；2.组建专项小组”）',
  `res_demand` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '资源需求，如“传感器3台（预算5万元）、人员5名”，资源信息表（biz_res_info）',
  `expected_effect` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '预期效果，如“事件响应时长缩短至20分钟内”',
  `scheme_status` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '方案状态：待审核/已通过/已驳回/已生效/已终止，标识方案生命周期状态',
  `apply_user_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '申请人ID，提交方案的分析师ID，用户信息表（sys_user）',
  `apply_user_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '申请人姓名，与申请人ID同步，用户信息表（sys_user）',
  `apply_time` datetime NOT NULL COMMENT '申请时间，格式：yyyy-MM-dd HH:mm:ss',
  `audit_user_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '审核人ID，审核方案的审核员ID，状态为“已通过/已驳回”时必填，用户信息表（sys_user）',
  `audit_user_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '审核人姓名，与审核人ID同步，用户信息表（sys_user）',
  `audit_time` datetime NULL DEFAULT NULL COMMENT '审核时间，格式：yyyy-MM-dd HH:mm:ss，状态为“已通过/已驳回”时必填',
  `audit_opinion` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '审核意见，审核反馈（如“同意方案，建议增加预算至6万元”）',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段1，预留，如“方案优先级”',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段2，预留，如“方案优先级”',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段1，预留，存储方案实施周期',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段2，预留，存储方案实施周期',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  `create_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '决策方案表' ROW_FORMAT = DYNAMIC;

