-- ----------------------------
-- Table structure for biz_dispatch_command
-- ----------------------------
DROP TABLE IF EXISTS `biz_dispatch_command`;
CREATE TABLE `biz_dispatch_command`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增主键ID',
  `command_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '指令ID，唯一编码，UUID生成',
  `command_no` char(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '指令编号，系统自动生成，格式“CMD_DISP+年份（4位）+6位流水号”',
  `plan_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '关联方案ID，关联调度方案表',
  `plan_no` char(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '方案编号，与方案ID同步，关联调度方案表（biz_dispatch_plan）',
  `exec_unit_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '执行单位ID，关联联动单位信息表',
  `exec_unit_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '执行单位名称，与执行单位ID同步，联动单位信息表（biz_coop_unit_info）',
  `task_content` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '任务内容，从方案同步，可补充细节，如“派遣2辆救援车，携带救生设备，1小时内到达XX内涝点”',
  `exec_requirement` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '执行要求，如“注意行车安全，到达后立即反馈”',
  `command_status` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '待下发' COMMENT '指令状态，待下发/已下发/已接收/执行中/已完成/已驳回，默认待下发',
  `issue_user_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '下发人ID，指令下发人账号，已下发时必填，关联用户信息表（sys_user）',
  `issue_user_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '下发人姓名，与下发人ID同步，关联用户信息表（sys_user）',
  `issue_time` datetime NULL DEFAULT NULL COMMENT '下发时间，格式yyyy-MM-dd HH:mm:ss，已下发时必填',
  `receive_user_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '接收人ID，执行单位接收人账号，已接收时必填，关联用户信息表（sys_user）',
  `receive_user_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '接收人姓名，与接收人ID同步，关联用户信息表（sys_user）',
  `receive_time` datetime NULL DEFAULT NULL COMMENT '接收时间，格式yyyy-MM-dd HH:mm:ss，已接收时必填',
  `exec_feedback` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '执行反馈，如“已派遣2辆救援车，预计30分钟后到达”',
  `complete_time` datetime NULL DEFAULT NULL COMMENT '完成时间，格式yyyy-MM-dd HH:mm:ss，已完成时必填',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分类扩展字段1，预留，如“指令紧急程度”',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分类扩展字段2，预留，如“指令紧急程度”',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '通用扩展字段1，预留，存储执行现场照片路径',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '通用扩展字段2，预留，存储执行现场照片路径',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '调度指令表' ROW_FORMAT = DYNAMIC;

