-- ----------------------------
-- Table structure for biz_dispatch_effect_feedback
-- ----------------------------
DROP TABLE IF EXISTS `biz_dispatch_effect_feedback`;
CREATE TABLE `biz_dispatch_effect_feedback`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增主键ID',
  `feedback_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '反馈ID，唯一编码，UUID生成',
  `command_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '关联指令ID，关联调度指令表',
  `command_no` char(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '指令编号，与指令ID同步，关联调度指令表（biz_dispatch_command）',
  `exec_unit_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '执行单位ID，与指令ID同步，联动单位信息表（biz_coop_unit_info）',
  `exec_unit_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '执行单位名称，与执行单位ID同步，联动单位信息表（biz_coop_unit_info）',
  `effect_desc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '执行效果描述，如“已按指令完成2辆救援车调度，转移被困人员20名，设备正常”',
  `feedback_attach_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '反馈附件路径，执行现场照片/视频路径，多个用逗号分隔',
  `feedback_user_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '反馈人ID，执行单位反馈人账号，关联用户信息表（sys_user）',
  `feedback_user_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '反馈人姓名，与反馈人ID同步，关联用户信息表（sys_user）',
  `feedback_time` datetime NOT NULL COMMENT '反馈时间，格式yyyy-MM-dd HH:mm:ss，系统自动生成',
  `eval_result` char(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '评估结果，有效/部分有效/无效，管理员评估结果',
  `eval_desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '评估说明，评估理由，如“救援及时，转移人员到位，效果有效”',
  `eval_user_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '评估人ID，管理员账号，评估后必填，关联用户信息表（sys_user）',
  `eval_time` datetime NULL DEFAULT NULL COMMENT '评估时间，格式yyyy-MM-dd HH:mm:ss，评估后必填',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分类扩展字段1，预留，如“效果评分（1-5分）”',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分类扩展字段2，预留，如“效果评分（1-5分）”',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '通用扩展字段1，预留，存储评估报告路径',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '通用扩展字段2，预留，存储评估报告路径',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '调度效果反馈表' ROW_FORMAT = DYNAMIC;

