-- ----------------------------
-- Table structure for biz_dispatch_plan
-- ----------------------------
DROP TABLE IF EXISTS `biz_dispatch_plan`;
CREATE TABLE `biz_dispatch_plan`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增主键ID',
  `plan_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '方案ID，唯一编码，UUID生成',
  `plan_no` char(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '方案编号，系统自动生成，格式“DISP+年份（4位）+6位流水号”',
  `resp_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '关联响应ID，关联预案启动响应表',
  `resp_no` char(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '响应编号，与响应ID同步，关联预案启动响应表（biz_plan_launch_resp）',
  `plan_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '方案名称，如“XX内涝救援资源调度方案”',
  `demand_desc` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '调度需求描述，如“需调配5辆救援车、200件救生衣至XX内涝点”',
  `res_type` char(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '资源类型，应急物资/救援队伍/救援车辆/救援设备，标识调度资源类型',
  `res_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '资源ID，关联对应资源表（物资/队伍等），应急物资信息表（biz_emer_mat_info）/救援队伍信息表（biz_emer_team_info）等',
  `res_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '资源名称，与资源ID同步，对应资源表',
  `dispatch_quantity` int NOT NULL COMMENT '调度数量，调度资源数量（物资/设备按单位，队伍按人数，车辆按辆）',
  `dispatch_dest` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '调配目的地，如“XX路与XX路交叉口内涝点”',
  `dest_coord_x` decimal(15, 2) NULL DEFAULT NULL COMMENT '目的地坐标X，度，2000国家大地坐标系经度',
  `dest_coord_y` decimal(15, 2) NULL DEFAULT NULL COMMENT '目的地坐标Y，度，2000国家大地坐标系纬度',
  `charger_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '负责人ID，调度负责人账号，关联用户信息表（sys_user）',
  `charger_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '负责人姓名，与负责人ID同步，关联用户信息表（sys_user）',
  `require_complete_time` datetime NOT NULL COMMENT '要求完成时间，格式yyyy-MM-dd HH:mm:ss',
  `plan_status` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '待执行' COMMENT '方案状态，待执行/执行中/已完成/已取消，默认待执行',
  `create_user` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '创建人，方案制定人账号，关联用户信息表（sys_user）',
  `create_time` datetime NOT NULL COMMENT '创建时间，格式yyyy-MM-dd HH:mm:ss，系统自动生成',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分类扩展字段1，预留，如“调度优先级”',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分类扩展字段2，预留，如“调度优先级”',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '通用扩展字段1，预留，存储调度路线规划路径',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '通用扩展字段2，预留，存储调度路线规划路径',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '调度方案表' ROW_FORMAT = DYNAMIC;

