-- ----------------------------
-- Table structure for biz_disposal_result_eval
-- ----------------------------
DROP TABLE IF EXISTS `biz_disposal_result_eval`;
CREATE TABLE `biz_disposal_result_eval`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `eval_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '评估ID，唯一编码，UUID生成',
  `trace_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联回溯ID，关联事件过程回溯表（biz_evt_process_trace）',
  `evt_code` char(18) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '事件编码，与回溯ID同步，来自事件接报登记表（biz_evt_rpt_reg）',
  `evt_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '事件名称，与事件编码同步，来自事件接报登记表（biz_evt_rpt_reg）',
  `efficacy_score` int NOT NULL COMMENT '处置效率得分，1-10分，评估接报-完成耗时、各环节时效，如“8分(总耗时4小时,符合预期)”',
  `efficacy_desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '处置效率说明，效率评估理由，如“接报后30分钟内完成研判,效率较高”',
  `res_score` int NOT NULL COMMENT '资源利用得分，1-10分，评估资源调配合理性、使用率，如“9分(冲锋舟全部投入使用,无浪费)”',
  `res_desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '资源利用说明，资源评估理由，如“按需调配5辆冲锋舟,无闲置”',
  `effect_score` int NOT NULL COMMENT '效果达成得分，1-10分，评估事件处置目标达成度，如“10分(被困20人全部转移,无伤亡)”',
  `effect_desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '效果达成说明，效果评估理由，如“处置目标全部达成,无次生灾害”',
  `comprehensive_score` decimal(4, 1) NOT NULL COMMENT '综合得分，(效率 + 资源 + 效果) / 3，保留1位小数',
  `improve_sugg` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '改进建议，如“下次内涝救援可提前预置冲锋舟至易涝点”',
  `eval_user_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '评估人ID，评估管理员账号，用户信息表（sys_user）',
  `eval_user_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '评估人姓名，与评估人ID同步，用户信息表（sys_user）',
  `eval_time` datetime NOT NULL COMMENT '评估时间，格式 yyyy-MM-dd HH:mm:ss，系统自动生成',
  `rpt_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '评估报告路径，PDF格式评估报告存储路径',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段1，预留，如“评估等级（优秀/良好/一般/差）”',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段2，预留，如“评估等级（优秀/良好/一般/差）”',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段1，预留，存储评估参考标准',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段2，预留，存储评估参考标准',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '处置结果评估表' ROW_FORMAT = DYNAMIC;

