  `device_count` int NOT NULL COMMENT '设备数量，该类型设备的总数量',
  `available_device_count` int NOT NULL COMMENT '可用数量，可投入救援的设备数量',
  `device_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '1' COMMENT '设备状态，1（正常）/0（异常），默认1',
