-- ----------------------------
-- Table structure for biz_emer_plan_lib
-- ----------------------------
DROP TABLE IF EXISTS `biz_emer_plan_lib`;
CREATE TABLE `biz_emer_plan_lib`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增主键ID',
  `plan_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '预案ID，唯一编码，UUID生成',
  `plan_no` char(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '预案编号，系统自动生成，格式“PLAN+年份(4位)+6位流水号”',
  `plan_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '预案标准名称，如“XX市2025年城市内涝应急预案”',
  `cat_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '分类ID，关联预案分类配置表',
  `cat_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '分类名称，拼接“大类 - 中类 - 小类”名称',
  `apply_region_code` char(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '适用区域代码，关联行政区划表',
  `apply_region_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '适用区域名称，与区域代码同步',
  `plan_version` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '预案版本，如“V1.0”“V2.1”',
  `effective_time` date NOT NULL COMMENT '生效时间，格式YYYYMMDD，预案生效日期',
  `expire_time` date NULL DEFAULT NULL COMMENT '失效时间，格式YYYYMMDD，预案失效日期',
  `plan_doc_path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '预案文档路径，PDF格式预案存储路径',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '预案库表' ROW_FORMAT = DYNAMIC;

