-- ----------------------------
-- Table structure for biz_emerg_res
-- ----------------------------
DROP TABLE IF EXISTS `biz_emerg_res`;
CREATE TABLE `biz_emerg_res`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号，自增主键',
  `res_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '资源ID，UUID格式，用于区分不同应急资源',
  `res_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '资源名称，最大100字符，如灭火器、急救包等',
  `res_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '资源类型，最大50字符，如应急物资/救援设备/医疗资源/救援队伍等',
  `mngr_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '负责人姓名，最大50字符',
  `mngr_id` bigint NOT NULL COMMENT '负责人ID，用户ID，默认值为0',
  `total_qty` int NOT NULL COMMENT '资源总数量，包含可用数量和调用数量的总和',
  `available_qty` int NOT NULL COMMENT '可用数量，应急资源中可立即调用的数量',
  `dispatch_qty` int NOT NULL COMMENT '调用数量，应急资源中被调用的数量',
  `min_stock` int NOT NULL COMMENT '最小库存量阈值，当库存低于此值时触发预警',
  `stock_status` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '库存状态，充足/紧张/短缺，根据可用数量判断',
  `storage_loc` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '存放位置',
  `coord_x` decimal(15, 2) NOT NULL COMMENT '经度坐标，单位度，范围：-180.00至180.00',
  `coord_y` decimal(15, 2) NOT NULL COMMENT '纬度坐标，单位度，范围：-90.00至90.00',
  `dist_region` char(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '资源分布区域，12位地区码，表示资源所在的具体区域',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间，记录被修改时自动更新',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 21 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '应急资源基础信息表' ROW_FORMAT = DYNAMIC;

