-- ----------------------------
-- Table structure for biz_evt_analysis
-- ----------------------------
DROP TABLE IF EXISTS `biz_evt_analysis`;
CREATE TABLE `biz_evt_analysis`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增主键ID',
  `analysis_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '研判ID，唯一编码，UUID',
  `evt_code` char(18) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '事件编码，关联事件接报登记表',
  `evt_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '事件名称，拼接“类型名称+事件名称”，如“交通拥堵 - XX路”',
  `analyst_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '研判人ID，研判分析师账号，关联用户信息表(sys_user)',
  `analyst_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '研判人姓名，与研判人ID同步',
  `analysis_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '研判时间，格式yyyy - MM - dd HH:mm:ss，系统自动生成',
  `evt_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '事件原因，研判的事件原因，如“交通事故导致XX路拥堵”',
  `impact_range` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '影响范围，描述影响范围，如“XX路1公里内，涉及2个小区”',
  `urgency_level` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '紧急程度，一般/紧急/特急，研判确定的紧急等级',
  `conclusion` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '研判结论，处置建议，如“优先调度交警处置事故，疏导车流”',
  `rel_mon_data_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '关联监测数据ID，关联监测部件数据表，如摄像头数据',
  `mon_data_abstract` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '监测数据摘要，监测数据简要描述，如“XX摄像头显示20辆车辆拥堵”',
  `need_allocate` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '是否需要分拨，1（是）/0（否），标识是否需后续分拨',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '事件研判分析表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of biz_evt_analysis
-- ----------------------------
