-- ----------------------------
-- Table structure for biz_evt_arch
-- ----------------------------
DROP TABLE IF EXISTS `biz_evt_arch`;
CREATE TABLE `biz_evt_arch`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增主键ID',
  `arch_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '归档ID，唯一编码，UUID',
  `wo_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '工单ID，关联事件工单表',
  `evt_code` char(18) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '事件编码，关联事件分级分拨表',
  `complete_time` datetime NOT NULL COMMENT '办结时间，格式yyyy - MM - dd HH:mm:ss',
  `complete_desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '办结说明',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '事件办结归档表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of biz_evt_arch
-- ----------------------------
INSERT INTO `biz_evt_arch` VALUES (1, '1', '1', '1', '2025-11-07 00:00:00', NULL, '1', '1', b'0', 1, '2025-11-19 14:45:49', '2025-11-19 14:45:49');

-- ----------------------------
-- Table structure for biz_evt_classify_allocate
-- ----------------------------
DROP TABLE IF EXISTS `biz_evt_classify_allocate`;
CREATE TABLE `biz_evt_classify_allocate`  (
  `allocate_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '唯一编码，UUID生成',
  `evt_code` char(18) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '关联事件研判分析表，外键参考：事件研判分析表（biz_evt_analysis）',
  `evt_type_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '关联事件类型配置表，外键参考：事件类型配置表（biz_evt_type_cfg）',
  `evt_type_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '与类型ID同步，来源：事件类型配置表（biz_evt_type_cfg）',
  `urgency_level` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '从研判表同步，取值：一般/紧急/特急，来源：事件研判分析表（biz_evt_analysis）',
  `allocate_dept_code` char(18) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '关联部门信息表，分拨目标部门，外键参考：部门信息表（sys_org）',
  `allocate_dept_name` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '与部门代码同步，来源：部门信息表（sys_org）',
  `allocator_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '分拨调度员账号，外键参考：用户信息表（sys_user）',
  `allocator_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '与分拨人ID同步，来源：用户信息表（sys_user）',
  `allocate_time` datetime NOT NULL COMMENT '格式yyyy-MM-dd HH:mm:ss，系统自动生成',
  `allocate_desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分拨备注，如\"优先处置，需1小时内反馈\"',
  `allocate_status` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '待接收' COMMENT '取值：待接收/已接收/已退回',
  `return_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分拨被退回时填写，如\"非本部门职责\"',
  `return_time` datetime NULL DEFAULT NULL COMMENT '格式yyyy-MM-dd HH:mm:ss，退回时必填',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '预留，如\"分拨规则ID\"',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '预留，如\"分拨规则ID\"',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '预留，存储分拨额外信息',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '预留，存储分拨额外信息',
  PRIMARY KEY (`allocate_id`) USING BTREE,
  INDEX `idx_evt_code`(`evt_code` ASC) USING BTREE,
  INDEX `idx_allocate_dept`(`allocate_dept_code` ASC) USING BTREE,
  INDEX `idx_allocate_time`(`allocate_time` ASC) USING BTREE,
  INDEX `idx_allocate_status`(`allocate_status` ASC) USING BTREE,
  INDEX `idx_evt_type`(`evt_type_id` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '事件分级分拨表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of biz_evt_classify_allocate
-- ----------------------------

-- ----------------------------
-- Table structure for biz_evt_disposal_track
-- ----------------------------
DROP TABLE IF EXISTS `biz_evt_disposal_track`;
CREATE TABLE `biz_evt_disposal_track`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增主键ID',
  `track_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '跟踪ID，唯一编码，UUID',
  `wo_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '工单ID，关联事件工单表',
  `handle_status` char(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '处置状态',
  `current_node` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '当前处置节点',
  `handler_name` char(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '处置人员',
  `start_time` datetime NOT NULL COMMENT '处置开始时间，格式yyyy - MM - dd HH:mm:ss',
  `est_complete_time` datetime NOT NULL COMMENT '预计完成时间，格式yyyy - MM - dd HH:mm:ss',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '事件处置跟踪表' ROW_FORMAT = DYNAMIC;

