-- ----------------------------
-- Table structure for biz_evt_rpt_reg
-- ----------------------------
DROP TABLE IF EXISTS `biz_evt_rpt_reg`;
CREATE TABLE `biz_evt_rpt_reg`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增主键ID',
  `rpt_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '接报ID，唯一编码，UUID',
  `evt_code` char(18) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '事件编码，系统自动生成，格式“6位区域码+2位大类码+3位小类码+7位顺序码”',
  `evt_type_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '事件类型ID，关联事件类型配置表小类ID',
  `evt_type_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '事件类型名称，与类型ID同步',
  `incident_region_code` char(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '事发区域代码，关联行政区划表',
  `incident_region_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '事发区域名称，与区域代码同步',
  `incident_location` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '事发位置，详细位置，如“XX路与XX路交叉口东北侧”',
  `incident_coord_x` decimal(15, 2) NULL DEFAULT NULL COMMENT '事发坐标X，度，2000国家大地坐标系经度',
  `incident_coord_y` decimal(15, 2) NULL DEFAULT NULL COMMENT '事发坐标Y，度，2000国家大地坐标系纬度',
  `evt_desc` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '事件描述，事件详情，如“商贩占用人行道售卖水果”',
  `deleted` tinyint(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除标记 0正常 1删除',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `tenant_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '创建人',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '更新者',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '事件接报登记表' ROW_FORMAT = DYNAMIC;

