-- ----------------------------
-- Table structure for biz_exp_lib
-- ----------------------------
DROP TABLE IF EXISTS `biz_exp_lib`;
CREATE TABLE `biz_exp_lib`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `exp_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '经验ID，唯一编码，UUID生成',
  `exp_no` char(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '经验编号，系统自动生成，格式“EXP+年份（4位）+6位流水号”',
  `exp_title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '经验标题，如“城市内涝救援冲锋舟预置经验”',
  `evt_type_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联事件类型ID，关联事件类型配置表小类ID，事件类型配置表（biz_evt_type_cfg）',
  `evt_type_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联事件类型名称，与类型ID同步，事件类型配置表（biz_evt_type_cfg）',
  `exp_type` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '经验类型，经验/教训，标识经验性质',
  `exp_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '经验内容，详细经验/教训，如“经验：内涝前24小时，将冲锋舟预置至XX、XX易涝点，缩短响应时间”',
  `eval_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关联评估ID，关联处置结果评估表，来源评估报告，处置结果评估表（biz_disposal_result_eval）',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '经验库表' ROW_FORMAT = DYNAMIC;

