-- ----------------------------
-- Table structure for biz_faq
-- ----------------------------
DROP TABLE IF EXISTS `biz_faq`;
CREATE TABLE `biz_faq`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `faq_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'FAQ ID，唯一编码，UUID生成',
  `question_type_code` char(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '问题类型代码，01=系统操作问题，02=业务数据问题，03=流程执行问题，问题类型字典表（sys_dict_question_type）',
  `question_type_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '问题类型名称，与问题类型代码同步，问题类型字典表（sys_dict_question_type）',
  `question_desc` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '问题描述，常见问题描述，如“地理编码坐标系配置失败怎么办？”',
  `answer_solution` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '解答方案，问题解决方案，支持富文本，如“1.检查坐标系代码是否重复；2.确认坐标系名称含‘坐标系’关键词”',
  `related_guide_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关联指南ID，关联操作指南/业务指南ID，如通用操作指南ID、专项业务指南ID，通用操作指南表（biz_general_oper_guide）/专项业务指南表（biz_spec_business_guide）',
  `related_guide_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关联指南名称，与关联指南ID同步，通用操作指南表（biz_general_oper_guide）/专项业务指南表（biz_spec_business_guide）',
  `sort_num` int NOT NULL COMMENT '排序序号，1 - 999，FAQ列表展示排序优先级，数值越小越靠前',
  `is_top` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '是否置顶，0 = 否，1 = 是，标识FAQ是否置顶展示（仅10条可置顶）',
  `view_count` int NOT NULL COMMENT '查看次数，用户查看FAQ的次数，默认0',
  `create_user` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '创建人，创建人ID，用户信息表（sys_user）',
  `create_time` datetime NOT NULL COMMENT '创建时间，格式yyyy - MM - dd HH:mm:ss，用户信息表（sys_user）',
  `update_user` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人，更新人ID，用户信息表（sys_user）',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间，格式yyyy - MM - dd HH:mm:ss，用户信息表（sys_user）',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段1，预留，如“问题难度：简单/中等/复杂”',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段2，预留，如“关联模块：地理编码/网格管理”',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段1，预留，如“解决率：98%”',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段2，预留，如“最后查看时间：2025 - 10 - 10”',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '常见问题解答表' ROW_FORMAT = DYNAMIC;

