-- ----------------------------
-- Table structure for biz_health_key_pop
-- ----------------------------
DROP TABLE IF EXISTS `biz_health_key_pop`;
CREATE TABLE `biz_health_key_pop`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增id',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '姓名',
  `region_full_code` char(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所在12位地区码',
  `risk_level` tinyint NOT NULL COMMENT '风险等级：1=高风险，0=低风险',
  `type` tinyint NOT NULL COMMENT '人群类型：0-老年人 / 1-慢性病患者 / 2-孕产妇',
  `record_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录的时间',
  `age` int NOT NULL COMMENT '年龄',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '重点人群健康表' ROW_FORMAT = DYNAMIC;

