DROP TABLE IF EXISTS `biz_health_org_svc`;
CREATE TABLE `biz_health_org_svc`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增id',
  `med_org_id` bigint NOT NULL COMMENT '对应医疗机构信息表sys_health_med_org的id',
  `stat_time` datetime NOT NULL COMMENT '统计时间',
  `bed_count` int NOT NULL COMMENT '床位数量',
  `bed_utilization_rate` double NOT NULL COMMENT '床位使用率（百分比）',
  `treat_volume` int NOT NULL COMMENT '机构接诊量',
  `surgery_count` int NOT NULL COMMENT '手术量',
  `region_full_code` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '所在地区（12位地区码）',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '医疗机构服务表' ROW_FORMAT = DYNAMIC;

