-- ----------------------------
-- Table structure for biz_health_warn
-- ----------------------------
DROP TABLE IF EXISTS `biz_health_warn`;
CREATE TABLE `biz_health_warn`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增id',
  `warn_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '预警id',
  `warn_level` int NOT NULL COMMENT '预警等级（多选：0-一般/1-较大/2-重大/3-特别重大）',
  `warn_type` int NOT NULL COMMENT '预警类型：0-传染病 / 1-公共卫生 / 2-医疗安全',
  `status` int NOT NULL COMMENT '状态：0-待处置 / 1-处置中 / 2-已完成',
  `discovery_time` datetime NOT NULL COMMENT '发生时间',
  `region_full_code` char(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '发现地区的12位区域码',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '卫健预警表' ROW_FORMAT = DYNAMIC;

