-- ----------------------------
-- Table structure for biz_industry_std
-- ----------------------------
DROP TABLE IF EXISTS `biz_industry_std`;
CREATE TABLE `biz_industry_std`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `industry_std_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '规范ID，唯一编码，UUID生成',
  `std_title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '规范标题，规范完整标题，如《城市物联网设备通用规范》',
  `industry_type_code` char(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '行业分类代码，取值如01=物联网，02=城管，03=交通，行业分类字典表（sys_dict_industry_type）',
  `industry_type_name` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '行业分类名称，与行业分类代码同步，行业分类字典表（sys_dict_industry_type）',
  `std_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '规范编号，行业标准编号（如“GB/T 39409-2020”）',
  `issue_org` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '发布机构，规范发布机构（如“中国城市科学研究会”）',
  `issue_time` datetime NOT NULL COMMENT '发布时间，格式：YYYYMMDD',
  `std_file_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '规范文件ID，关联文件存储表的文件ID，文件存储表（sys_file_storage）',
  `std_file_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '规范文件路径，规范文件存储路径，文件存储表（sys_file_storage）',
  `std_status` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '规范状态：现行/废止，标识规范当前状态',
  `core_clause` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '核心条款，规范核心条款摘要（≤1000字）',
  `create_user` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '创建人，创建人ID，用户信息表（sys_user）',
  `create_time` datetime NOT NULL COMMENT '创建时间，格式：yyyy-MM-dd HH:mm:ss',
  `update_user` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人，更新人ID，用户信息表（sys_user）',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间，格式：yyyy-MM-dd HH:mm:ss',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段1，预留，如“规范等级：国家/行业”',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段2，预留，如“适用场景：设备采购/数据录入”',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段1，预留，如“规范下载链接”',
