  `biz_create_time` datetime NULL DEFAULT NULL COMMENT '创建时间（业务）',
  `update_user` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `biz_update_time` datetime NULL DEFAULT NULL COMMENT '更新时间（业务）',
