-- ----------------------------
-- Table structure for biz_law_enf_device
-- ----------------------------
DROP TABLE IF EXISTS `biz_law_enf_device`;
CREATE TABLE `biz_law_enf_device`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `device_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '设备唯一标识（UUID）',
  `online_status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '在线状态（0-离线，1-在线）',
  `region_full_code` char(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '所属行政区划全代码（GB/T 2260）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后更新时间',
  `create_user` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建人',
  `is_delete` tinyint(1) NOT NULL DEFAULT 0 COMMENT '删除标记（0-未删除，1-已删除）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_device_id`(`device_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '执法设备表' ROW_FORMAT = DYNAMIC;

