-- ----------------------------
DROP TABLE IF EXISTS `biz_local_level_exp`;
CREATE TABLE `biz_local_level_exp`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `local_level_exp_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '经验ID，唯一编码，UUID生成',
  `exp_title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '经验标题，如“XX市东城区网格划分经验”',
  `region_code` char(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '行政区划代码，本级行政区划代码，如330106=杭州市西湖区，行政区划表（sys_area）',
  `region_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '行政区划名称，与行政区划代码同步，行政区划表（sys_area）',
  `dept_code` char(18) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联部门代码，经验来源部门代码，部门信息表（sys_org）',
  `dept_name` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联部门名称，与关联部门代码同步，部门信息表（sys_org）',
  `exp_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '经验详细内容，支持富文本，如“网格划分原则：按人口密度、地理边界划分”',
  `implementation_steps` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '经验实施步骤，如“1.调研区域人口；2.绘制地理边界；3.划分单元网格”',
  `achievement_data` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '实施成果，如“划分网格200个，事件处置效率提升30%”',
  `attach_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '附件ID，关联经验附件ID（如划分方案、成果报表），文件存储表（sys_file_storage）',
  `attach_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '附件存储路径，文件存储表（sys_file_storage）',
  `publish_status` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '发布状态：已发布/草稿，标识经验是否公开',
  `share_count` int NOT NULL COMMENT '分享次数，用户分享经验的次数，默认0',
  `create_user` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '创建人，创建人ID，用户信息表（sys_user）',
  `create_time` datetime NOT NULL COMMENT '创建时间，格式：yyyy-MM-dd HH:mm:ss',
  `update_user` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人，更新人ID，用户信息表（sys_user）',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间，格式：yyyy-MM-dd HH:mm:ss',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段1，预留，如“经验领域：网格管理/事件处置”',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段2，预留，如“分享范围：本级/下级”',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段1，预留，如“实施时间：2025年1月”',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段2，预留，如“最后分享时间：2025-10-10”',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '本级经验分享表' ROW_FORMAT = DYNAMIC;

