-- ----------------------------
DROP TABLE IF EXISTS `biz_mng_comp_spatial`;
CREATE TABLE `biz_mng_comp_spatial`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `mng_comp_spatial_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '空间数据ID，唯一编码，UUID生成',
  `mng_comp_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '关联管理部件ID，一对一',
