-- ----------------------------
-- Table structure for biz_mon_comp_info
-- ----------------------------
DROP TABLE IF EXISTS `biz_mon_comp_info`;
CREATE TABLE `biz_mon_comp_info`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `mon_comp_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '部件ID，唯一编码，UUID生成',
  `comp_code` char(18) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '部件标识码，按18位规则生成，如110101010200100001；监测部件标识码规则表(sys_mon_comp_code_rule)',
  `comp_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '部件名称，关联分类名称，如“燃气压力传感器”；监测部件分类配置表(sys_mon_comp_cat)',
  `comp_cat_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '部件分类ID，关联监测部件分类表小类ID；监测部件分类配置表(sys_mon_comp_cat)',
  `dept_code` char(18) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主管部门代码，主管部门统一社会信用代码；部门信息表(sys_org)',
  `dept_name` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主管部门名称，与部门代码同步，自动填充；部门信息表(sys_org)',
  `region_code` char(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所在行政区域代码，符合GB/T 2260，县级行政区域代码；行政区划表(sys_area)',
  `region_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所在行政区域名称，与行政代码同步，自动填充；行政区划表(sys_area)',
  `grid_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所在网格ID，关联单元网格ID；单元网格划分表(biz_unit_grid_div)',
  `grid_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所在网格名称，与网格ID同步，自动填充；单元网格划分表(biz_unit_grid_div)',
  `coord_x` decimal(15, 2) NOT NULL COMMENT '坐标X，经度，2000国家大地坐标系',
  `coord_y` decimal(15, 2) NOT NULL COMMENT '坐标Y，纬度，2000国家大地坐标系',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '监测部件信息表' ROW_FORMAT = DYNAMIC;

