-- ----------------------------
-- Table structure for biz_mon_evt_info
-- ----------------------------
DROP TABLE IF EXISTS `biz_mon_evt_info`;
CREATE TABLE `biz_mon_evt_info`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `mon_evt_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '事件ID，唯一编码，UUID生成',
  `evt_code` char(18) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '事件标识码，按18位规则生成，如110101020300200001；监测事件标识码规则表 (sys_mon_evt_code_rule)',
  `evt_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '事件名称，关联分类名称，如 “燃气泄漏事件”；监测事件分类配置表 (sys_mon_evt_cat)',
  `evt_cat_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '事件分类ID，关联事件分类表小类ID，监测事件分类配置表 (sys_mon_evt_cat)',
  `rel_comp_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联部件ID，关联监测部件信息表部件ID，监测部件信息表 (biz_mon_comp_info)',
  `rel_comp_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联部件名称，与部件ID同步，自动填充，监测部件信息表 (biz_mon_comp_info)',
  `incident_pos` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '事发位置，事件发生位置，如 “XX路与XX路交叉口”',
  `incident_x` decimal(15, 2) NOT NULL COMMENT '事发坐标X，经度，2000国家大地坐标系',
  `incident_y` decimal(15, 2) NOT NULL COMMENT '事发坐标Y，纬度，2000国家大地坐标系',
  `evt_level` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '事件等级，一级/二级/三级，事件严重程度，参照GB/T XXXXX.6',
  `handle_status` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '处置状态，待处置/处置中/已办结/已驳回，事件处置进度',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '监测事件信息表' ROW_FORMAT = DYNAMIC;

