-- ----------------------------
-- Table structure for biz_national_pol
-- ----------------------------
DROP TABLE IF EXISTS `biz_national_pol`;
CREATE TABLE `biz_national_pol`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `national_pol_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '政策ID，唯一编码，UUID生成',
  `pol_title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '政策标题，政策完整标题，如《“十四五”智慧城市发展规划》',
  `pol_doc_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '政策文号，政府发布文号（如“发改高技〔2021〕1602号”）',
  `issue_dept_code` char(18) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '发布部门代码，发布部门统一社会信用代码，部门信息表（sys_org）',
  `issue_dept_name` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '发布部门名称，与发布部门代码同步，部门信息表（sys_org）',
  `issue_time` datetime NOT NULL COMMENT '发布时间，格式：YYYYMMDD，政策发布日期',
  `implement_time` datetime NULL DEFAULT NULL COMMENT '实施时间，格式：YYYYMMDD，政策实施日期（未明确则为空）',
  `pol_file_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '政策文件ID，关联文件存储表的文件ID，文件存储表（sys_file_storage）',
  `pol_file_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '政策文件路径，政策文件服务器存储路径，文件存储表（sys_file_storage）',
  `pol_status` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '政策状态：有效/失效，标识政策当前状态',
  `pol_summary` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '政策摘要，政策核心内容摘要（≤500字）',
  `create_user` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '创建人，创建人ID，用户信息表（sys_user）',
  `create_time` datetime NOT NULL COMMENT '创建时间，格式：yyyy-MM-dd HH:mm:ss',
  `update_user` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人，更新人ID，用户信息表（sys_user）',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间，格式：yyyy-MM-dd HH:mm:ss',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段1，预留，如“政策分类：发展规划/技术标准”',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段2，预留，如“适用领域：城管/交通/环保”',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段1，预留，如“政策来源链接：https://www.gov.cn/...”',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段2，预留，如“版本号：V1.0”',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time_sys` datetime(6) NULL DEFAULT NULL COMMENT '系统创建时间',
  `update_time_sys` datetime(6) NULL DEFAULT NULL COMMENT '系统更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '国家政策信息表' ROW_FORMAT = DYNAMIC;

