-- ----------------------------
-- Table structure for biz_park_berth_lock
-- ----------------------------
DROP TABLE IF EXISTS `biz_park_berth_lock`;
CREATE TABLE `biz_park_berth_lock`  (
  `id` bigint NULL DEFAULT NULL COMMENT '主键，唯一标识',
  `reservation_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '关联预约ID',
  `berth_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '锁定的泊位唯一标识',
  `lock_start_time` datetime NULL DEFAULT NULL COMMENT '锁定开始时间',
  `lock_end_time` datetime NULL DEFAULT NULL COMMENT '锁定结束时间',
  `lock_status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '泊位锁定状态',
  `unlock_reason` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '泊位解锁原因',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NULL DEFAULT NULL COMMENT '逻辑删除标识（0 未删除，1 已删除）',
  `tenant_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '租户ID',
  `ext_cat1` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分类扩展字段1',
  `ext_cat2` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分类扩展字段2',
  `ext_common1` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '通用扩展字段1',
  `ext_common2` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '通用扩展字段2'
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '泊位锁定记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of biz_park_berth_lock
-- ----------------------------

-- ----------------------------
-- Table structure for biz_park_discount_activity
-- ----------------------------
DROP TABLE IF EXISTS `biz_park_discount_activity`;
CREATE TABLE `biz_park_discount_activity`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键，记录唯一标识',
  `discount_activity_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '优惠活动唯一编号',
  `activity_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '优惠活动名称',
  `discount_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '优惠活动类型',
  `discount_rule` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '优惠计算或使用规则',
  `discount_amount` decimal(10, 2) NULL DEFAULT NULL COMMENT '单笔立减金额',
  `status` tinyint NOT NULL DEFAULT 1 COMMENT '活动状态（0-停用，1-进行中）',
  `total_discount_amount` decimal(12, 2) NULL DEFAULT 0.00 COMMENT '活动累计优惠金额',
  `participate_order_count` int NULL DEFAULT 0 COMMENT '参与活动的订单数量',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '记录创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '记录更新者',
  `create_time` datetime NOT NULL COMMENT '记录创建时间',
  `update_time` datetime NOT NULL COMMENT '记录更新时间',
  `deleted` tinyint(1) NULL DEFAULT 0 COMMENT '逻辑删除标识（0-未删除，1-已删除）',
  `tenant_id` bigint NOT NULL COMMENT '租户唯一标识',
  `ext_cat1` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分类扩展字段1',
  `ext_cat2` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分类扩展字段2',
  `ext_common1` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '通用扩展字段1',
  `ext_common2` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '通用扩展字段2',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '优惠活动表' ROW_FORMAT = DYNAMIC;

