-- ----------------------------
-- Table structure for biz_park_real_time
-- ----------------------------
DROP TABLE IF EXISTS `biz_park_real_time`;
CREATE TABLE `biz_park_real_time`  (
  `id` bigint NULL DEFAULT NULL COMMENT '主键，唯一标识',
  `recommend_park_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '推荐停车场唯一标识',
  `free_space` int NULL DEFAULT NULL COMMENT '当前剩余可用泊位数量',
  `occupy_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '泊位占用比例（百分比）',
  `update_time` datetime NULL DEFAULT NULL COMMENT '记录更新时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
