-- ----------------------------
-- Table structure for biz_park_release_record
-- ----------------------------
DROP TABLE IF EXISTS `biz_park_release_record`;
CREATE TABLE `biz_park_release_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键，唯一标识',
  `pay_id` bigint NOT NULL COMMENT '关联缴费记录标识',
  `release_cmd_id` bigint NOT NULL COMMENT '放行指令唯一标识',
  `release_status` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '放行状态（未放行，已放行）',
  `release_time` datetime NULL DEFAULT NULL COMMENT '实际放行时间',
  `gate_id` bigint NULL DEFAULT NULL COMMENT '闸机唯一标识',
  `operator_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '执行放行操作人员',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `deleted` tinyint NOT NULL DEFAULT 0 COMMENT '删除标识（0-未删除，1-已删除）',
  `tenant_id` bigint NULL DEFAULT NULL COMMENT '租户ID',
  `ext_cat1` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分类扩展字段1',
  `ext_cat2` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分类扩展字段2',
  `ext_common1` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '通用扩展字段1',
  `ext_common2` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '通用扩展字段2',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '放行记录表' ROW_FORMAT = DYNAMIC;

