-- ----------------------------
-- Table structure for biz_park_wo
-- ----------------------------
DROP TABLE IF EXISTS `biz_park_wo`;
CREATE TABLE `biz_park_wo`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID，唯一标识',
  `wo_id` bigint NOT NULL COMMENT '订单ID，唯一标识',
  `wo_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '订单编号',
  `park_id` bigint NOT NULL COMMENT '停车场ID',
  `park_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '停车场名称',
  `park_endure` int NOT NULL COMMENT '停车时长（分钟）',
  `receivable_amount` decimal(10, 2) NOT NULL COMMENT '应收金额',
  `pay_status` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '支付状态（待支付、已支付)',
  `arrears_reason` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '欠费原因说明(已支付情况下为空）',
  `deleted` tinyint NULL DEFAULT 0 COMMENT '逻辑删除标识（0 未删除，1 已删除）',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `tenant_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '租户ID',
  `ext_cat1` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分类扩展字段1',
  `ext_cat2` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分类扩展字段2',
  `ext_common1` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '通用扩展字段1',
  `ext_common2` varchar(256) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '通用扩展字段2',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10008 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '停车订单表' ROW_FORMAT = DYNAMIC;

