-- ----------------------------
-- Table structure for biz_plan_launch_resp
-- ----------------------------
DROP TABLE IF EXISTS `biz_plan_launch_resp`;
CREATE TABLE `biz_plan_launch_resp`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增主键ID',
  `resp_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '响应ID，唯一编码，UUID',
  `resp_no` char(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '响应编号，系统自动生成，格式“RESP+年份（4位）+6位流水号”',
  `plan_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '关联预案ID，关联预案库表',
  `plan_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '预案名称，与预案ID同步',
  `plan_version` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '预案版本，与预案ID同步',
  `evt_code` char(18) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '关联事件编码，关联事件接报登记表，无事件时为空',
  `evt_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '事件名称，与事件编码同步',
  `launch_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '启动原因，如“XX区域3小时降雨量超150mm，引发内涝，需启动III级响应”',
  `resp_level` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '响应等级，IV级/III级/II级/I级，按事件严重程度选择',
  `launch_user_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '启动人ID，预案启动管理员账号，关联用户信息表（sys_user）',
  `launch_user_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '启动人姓名，与启动人ID同步',
  `launch_time` datetime NOT NULL COMMENT '启动时间，格式yyyy-MM-dd HH:mm:ss，系统自动生成',
  `resp_status` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '启动中' COMMENT '响应状态，启动中/响应完成/响应终止，默认启动中',
  `terminate_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '终止原因，响应终止时填写，如“内涝已缓解，无需继续响应”',
  `terminate_time` datetime NULL DEFAULT NULL COMMENT '终止时间，格式yyyy-MM-dd HH:mm:ss，响应终止时必填',
  `sync_unit_ids` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '需同步的联动单位ID，多个用逗号分隔，关联联动单位信息表（biz_coop_unit_info）',
  `sync_unit_names` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '与单位IDs同步，关联联动单位信息表（biz_coop_unit_info）',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '预留，如“响应指挥长”',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '预留，如“响应指挥长”',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '预留，存储响应部署方案路径',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '预留，存储响应部署方案路径',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '预案启动响应表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of biz_plan_launch_resp
-- ----------------------------
INSERT INTO `biz_plan_launch_resp` VALUES (1, '1', '121', '2131', '23', '12', '12', '2', '2123', '12', '12', '12', '2025-11-27 00:00:00', '启动中', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '1', '1', b'0', 1, '2025-11-19 15:54:01', '2025-11-19 15:54:01');

-- ----------------------------
-- Table structure for biz_pol_compliance_ck
-- ----------------------------
DROP TABLE IF EXISTS `biz_pol_compliance_ck`;
CREATE TABLE `biz_pol_compliance_ck`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `compliance_ck_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '校验ID，唯一编码，UUID生成',
  `rel_scheme_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联方案ID，关联决策方案表的方案ID，决策方案表（biz_decision_scheme）',
  `rel_scheme_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联方案名称，与方案ID同步，决策方案表（biz_decision_scheme）',
  `ck_pol_ids` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '校验政策IDs，关联政策法规库表的政策ID，逗号分隔，政策法规库表（sys_pol_library）',
  `ck_pol_names` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '校验政策名称，与政策IDs同步，逗号分隔，政策法规库表（sys_pol_library）',
  `ck_status` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '校验状态：待校验/校验中/已通过/存在风险，标识校验进度',
  `risk_level` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '风险等级：无/低/中/高，校验状态为“存在风险”时必填',
  `risk_pt_count` int NULL DEFAULT NULL COMMENT '风险点数量，个，校验出的风险点总数，合规校验结果表（biz_compliance_ck_result）',
  `compliance_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '合规率，%，(校验项总数-风险点数量)/校验项总数×100，0.00-100.00',
  `ck_conclusion` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '校验结论，如“方案存在2个中风险点，需整改后实施”',
  `ck_user` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '校验人，发起校验的用户ID，用户信息表（sys_user）',
  `ck_time` datetime NOT NULL COMMENT '校验时间，格式：yyyy-MM-dd HH:mm:ss',
  `rectification_sugg` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '整改建议，针对风险点的整改方向（如“设备高度降至8米以内，补充安全评估报告”）',
  `review_status` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '复核状态：待复核/复核通过/复核驳回，风险整改后复核状态',
  `review_user` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '复核人，复核用户ID，复核状态非“待复核”时必填，用户信息表（sys_user）',
  `review_time` datetime NULL DEFAULT NULL COMMENT '复核时间，格式：yyyy-MM-dd HH:mm:ss，复核状态非“待复核”时必填',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段1，预留，如“校验批次”',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段2，预留，如“校验批次”',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段1，预留，存储政策版本号',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段2，预留，存储政策版本号',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 20 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '政策合规校验表' ROW_FORMAT = DYNAMIC;

