-- ----------------------------
-- Table structure for biz_pol_interpretation
-- ----------------------------
DROP TABLE IF EXISTS `biz_pol_interpretation`;
CREATE TABLE `biz_pol_interpretation`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `pol_interpretation_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '解读ID，唯一编码，UUID生成',
  `related_pol_type` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联政策类型，取值为国家政策/地方法规，标识关联政策类型',
  `related_pol_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联政策ID，关联国家政策/地方法规ID，国家政策信息表（biz_national_pol）/地方法规信息表（biz_local_regulation）',
  `related_pol_title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联政策标题，与关联政策ID同步，国家政策信息表（biz_national_pol）/地方法规信息表（biz_local_regulation）',
  `interpretation_title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '解读标题，如《“十四五”智慧城市发展规划解读》',
  `interpretation_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '解读详细内容（支持富文本）',
  `interpreter_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '解读人ID，解读人账号，用户信息表（sys_user）',
