  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间，格式：yyyy-MM-dd HH:mm:ss',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段1，预留，如“流程类型：事件处置/设备报修”',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段2，预留，如“适用角色：管理员/处置员”',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段1，预留，如“制定依据：XX业务标准”',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段2，预留，如“修订时间：2024-10-01”',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
