-- ----------------------------
-- Table structure for biz_public_ai_svc
-- ----------------------------
DROP TABLE IF EXISTS `biz_public_ai_svc`;
CREATE TABLE `biz_public_ai_svc`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `ai_svc_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '知识库ID，唯一编码，UUID生成',
  `question_type_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '问题类型编码，问题分类，如“社保”“公积金”，字典表（sys_dict）',
  `question_type_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '问题类型名称，与类型编码同步，字典表（sys_dict）',
  `question_keyword` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '问题关键词，多个关键词用逗号分隔，如“个税查询,个税缴纳记录”',
  `std_question` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标准问题，规范化问题表述，如“如何查询个税缴纳记录”',
  `std_answer` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标准答案，分点回复，支持富文本',
  `attach_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '附件路径，辅助说明附件，如操作截图',
  `use_count` int NOT NULL COMMENT '使用次数，智能回复时累计次数，默认0',
  `update_time` datetime(3) NOT NULL COMMENT '更新时间，知识库更新时间',
  `update_user_id` bigint NOT NULL COMMENT '更新人ID，更新人ID，用户表（sys_user）',
  `update_user_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '更新人姓名，与更新人ID同步，用户表（sys_user）',
  `enable_status` tinyint NOT NULL COMMENT '启用状态：1=启用，0=禁用，标识是否参与智能匹配',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注，补充说明，如“高频问题，优先匹配”',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段1，预留，标识问题难度，如简单/复杂',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段2，预留，标识回复类型，如文本/图文',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段1，预留，存储人工客服转办阈值',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段2，预留，存储关键词匹配阈值',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  `create_time` datetime(6) NULL DEFAULT NULL COMMENT '系统创建时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 4 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '智能客服知识库表' ROW_FORMAT = DYNAMIC;

