  `consult_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '咨询单号，格式“ZX+YYYYMMDD+6位流水号”',
  `consult_type_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '咨询类型编码，类型（如“政策咨询”“建设建议”），字典表（sys_dict）',
  `consult_type_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '咨询类型名称，与类型编码同步，字典表（sys_dict）',
  `consult_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '咨询内容，市民咨询或建议内容',
  `contact_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '联系人姓名，咨询人姓名',
  `contact_phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '联系人电话，加密存储',
  `accept_dept_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '受理部门编码，受理部门，部门信息表（sys_org）',
  `accept_dept_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '受理部门名称，与部门编码同步，部门信息表（sys_org）',
  `reply_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '回复内容，部门回复内容',
  `consult_status` tinyint NOT NULL COMMENT '咨询状态：1=待回复，2=已回复，3=已采纳（建议类），流程状态',
  `submit_time` datetime(3) NOT NULL COMMENT '提交时间，市民提交时间',
