-- ----------------------------
-- Table structure for biz_public_feedback
-- ----------------------------
DROP TABLE IF EXISTS `biz_public_feedback`;
CREATE TABLE `biz_public_feedback`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `feedback_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '反馈ID，唯一编码，UUID生成',
  `feedback_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '反馈单号，格式“FK+YYYYMMDD+6位流水号”',
  `feedback_type_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '反馈类型编码，类型（如“功能问题”“优化建议”），字典表（sys_dict）',
  `feedback_type_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '反馈类型名称，与类型编码同步，字典表（sys_dict）',
  `feedback_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '反馈内容，市民反馈的问题或建议',
  `img_path` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '上传图片路径，问题截图，多个用逗号分隔',
  `feedback_user_id` bigint NULL DEFAULT NULL COMMENT '反馈人ID，登录用户ID（未登录为空），用户表（sys_user）',
  `feedback_user_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '反馈人姓名',
  `feedback_user_phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '反馈人电话，加密存储（便于回访）',
  `eval_status` tinyint NOT NULL COMMENT '评估状态：1=待评估，2=已采纳，3=不采纳，评估结果',
  `eval_opinion` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '评估意见，管理员评估说明，如“采纳，下版本优化”',
  `eval_user_id` bigint NULL DEFAULT NULL COMMENT '评估人ID，评估管理员ID，用户表（sys_user）',
  `eval_time` datetime(3) NULL DEFAULT NULL COMMENT '评估时间',
  `feedback_time` datetime(3) NOT NULL COMMENT '反馈时间，市民提交时间',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注，补充说明，如“已联系用户回访”',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段1，预留，标识反馈模块，如投诉/咨询',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段2，预留，标识紧急程度，如普通/紧急',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段1，预留，存储优化版本号',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段2，预留，存储回访结果',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  `create_time` datetime(6) NULL DEFAULT NULL COMMENT '系统创建时间',
  `update_time` datetime(6) NULL DEFAULT NULL COMMENT '系统更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '意见反馈表' ROW_FORMAT = DYNAMIC;

