-- ----------------------------
-- Table structure for biz_public_hotline_link
-- ----------------------------
DROP TABLE IF EXISTS `biz_public_hotline_link`;
CREATE TABLE `biz_public_hotline_link`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `hotline_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '热线ID，唯一编码，UUID生成',
  `hotline_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '热线单号，热线系统原生单号，如“12345-20251014-001”',
  `platform_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '平台单号，平台生成单号，格式“RL+YYYYMMDD+6位流水号”',
  `appeal_type_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '诉求类型编码，热线诉求类型，字典表（sys_dict）',
  `appeal_type_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '诉求类型名称，与类型编码同步，字典表（sys_dict）',
  `area_code` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '事发区域编码，事发区域编码，区域表（sys_area）',
  `area_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '事发区域名称，与区域编码同步，区域表（sys_area）',
  `appeal_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '诉求内容，市民诉求详情',
  `contact_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '联系人姓名，热线记录的联系人姓名',
  `contact_phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '联系人电话，加密存储',
  `hotline_source` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '热线来源，如“12345”“12319”',
  `sync_status` tinyint NOT NULL COMMENT '同步状态：1=待同步，2=已同步，3=同步失败，数据同步状态',
  `handle_status` tinyint NOT NULL COMMENT '处置状态：1=待受理，2=已受理，3=处置中，4=已办结，5=已驳回，处置流程状态',
  `accept_dept_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '受理部门编码，受理部门，部门信息表（sys_org）',
  `accept_dept_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '受理部门名称，与部门编码同步，部门信息表（sys_org）',
  `handle_result` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '处置结果，处置完成后填写',
  `sync_time` datetime(3) NULL DEFAULT NULL COMMENT '同步时间，数据同步至平台的时间',
  `finish_time` datetime(3) NULL DEFAULT NULL COMMENT '办结时间，处置完成时间',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段1，预留，标识热线优先级，如普通/紧急',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段2，预留，标识诉求来源，如电话/短信',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段1，预留，存储热线受理时间',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段2，预留，存储热线备注',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  `create_time` datetime(6) NULL DEFAULT NULL COMMENT '系统创建时间',
  `update_time` datetime(6) NULL DEFAULT NULL COMMENT '系统更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '热线对接表' ROW_FORMAT = DYNAMIC;

