-- ----------------------------
-- Table structure for biz_public_notice
-- ----------------------------
DROP TABLE IF EXISTS `biz_public_notice`;
CREATE TABLE `biz_public_notice`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `notice_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '通知ID，唯一编码，UUID生成',
  `notice_title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '通知标题，通知核心标题，需明确信息类型，如“XX区域停水通知”',
  `notice_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '通知内容，通知详细内容，支持富文本（图片、表格）',
  `dept_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '发布部门编码，发布通知的部门编码，部门信息表（sys_org）',
  `dept_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '发布部门名称，与部门编码同步，不可手动修改，部门信息表（sys_org）',
  `publish_user_id` bigint NOT NULL COMMENT '发布人ID，发布操作人ID，用户表（sys_user）',
  `publish_user_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '发布人姓名，与发布人ID同步，用户表（sys_user）',
  `publish_time` datetime(3) NOT NULL COMMENT '发布时间，点击“发布”时系统自动生成，格式yyyy-MM-dd HH:mm:ss',
  `notice_status` tinyint NOT NULL COMMENT '通知状态：1=草稿，2=已发布，3=已撤回，控制通知展示状态',
  `effective_time` datetime(3) NOT NULL COMMENT '生效时间，通知开始向公众展示的时间',
  `expire_time` datetime(3) NOT NULL COMMENT '失效时间，通知停止展示的时间，需晚于生效时间',
  `attach_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '附件路径，通知附件（如检修方案）存储路径',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注，补充说明，如“紧急通知，请优先展示”',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段1，预留，标识通知类型（停水/停电/活动）',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段2，预留，标识通知级别（普通/紧急）',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段1，预留，存储附件名称',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段2，预留，存储发布终端（PC/APP）',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  `create_time` datetime(6) NULL DEFAULT NULL COMMENT '系统创建时间',
  `update_time` datetime(6) NULL DEFAULT NULL COMMENT '系统更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '通知公告发布表' ROW_FORMAT = DYNAMIC;

