-- ----------------------------
-- Table structure for biz_public_online_interview
-- ----------------------------
DROP TABLE IF EXISTS `biz_public_online_interview`;
CREATE TABLE `biz_public_online_interview`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `interview_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '访谈ID，唯一编码，UUID生成',
  `interview_topic` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '访谈主题，访谈核心主题，如“社保新政在线访谈”',
  `dept_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '访谈单位编码，主办部门编码，部门信息表（sys_org）',
  `dept_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '访谈单位名称，与部门编码同步，部门信息表（sys_org）',
  `guest_info` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '嘉宾信息，嘉宾姓名、职务、简介，多个用逗号分隔',
  `interview_time` datetime(3) NOT NULL COMMENT '访谈时间，访谈开始时间，格式“yyyy-MM-dd HH:mm”',
  `interview_endure` int NOT NULL COMMENT '访谈时长，访谈预计时长，单位：分钟，如60=1小时',
  `interview_status` tinyint NOT NULL COMMENT '访谈状态：1=未开始，2=进行中，3=已结束，4=实录公示，流程状态',
  `question_count` int NOT NULL COMMENT '提问总数，市民提问累计数量，默认0',
  `reply_count` int NOT NULL COMMENT '回复总数，嘉宾回复累计数量，默认0',
  `rec_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '实录内容，访谈后整理的问答实录，支持富文本',
  `rec_publish_time` datetime(3) NULL DEFAULT NULL COMMENT '实录发布时间，实录公示的时间',
  `publish_user_id` bigint NOT NULL COMMENT '发布人ID，发布访谈的人员ID，用户表（sys_user）',
  `publish_user_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '发布人姓名，与发布人ID同步，用户表（sys_user）',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注，补充说明，如“访谈将在抖音同步直播”',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段1，预留，标识访谈形式，如纯文字/视频',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段2，预留，标识访谈平台，如官网/APP',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段1，预留，存储直播链接',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段2，预留，存储实录下载地址',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  `create_time` datetime(6) NULL DEFAULT NULL COMMENT '系统创建时间',
  `update_time` datetime(6) NULL DEFAULT NULL COMMENT '系统更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '在线访谈表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
