-- ----------------------------
-- Table structure for biz_public_opinion_collect
-- ----------------------------
DROP TABLE IF EXISTS `biz_public_opinion_collect`;
CREATE TABLE `biz_public_opinion_collect`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `collect_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '征集ID，唯一编码，UUID生成',
  `collect_topic` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '征集主题，征集核心主题，如“XX片区改造规划征集”',
  `dept_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '征集单位编码，发布征集的部门编码，部门信息表（sys_org）',
  `dept_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '征集单位名称，与部门编码同步，部门信息表（sys_org）',
  `area_code` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '征集范围编码，征集覆盖区域编码，如“330100”=杭州市，区域表（sys_area）',
  `area_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '征集范围名称，与区域编码同步，区域表（sys_area）',
  `collect_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '征集内容，征集背景、需反馈的问题',
  `start_time` datetime(3) NOT NULL COMMENT '开始时间，征集开始时间',
  `end_time` datetime(3) NOT NULL COMMENT '结束时间，征集结束时间',
  `collect_status` tinyint NOT NULL COMMENT '征集状态：1=未开始，2=征集ing，3=已结束，4=结果公示，流程状态',
  `result_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '结果公示内容，征集结束后公示的汇总结果',
  `publish_result_time` datetime(3) NULL DEFAULT NULL COMMENT '公示时间，结果公示时间',
  `publish_user_id` bigint NOT NULL COMMENT '发布人ID，发布征集的人员ID，用户表（sys_user）',
  `publish_time` datetime(3) NOT NULL COMMENT '发布时间，发布征集的时间',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注，补充说明，如“纸质意见可邮寄至XX地址”',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段1，预留，标识征集类型，如规划/政策',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段2，预留，标识征集级别，如市级/区级',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段1，预留，存储意见提交方式，如线上/线下',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段2，预留，存储意见统计数量',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  `create_time` datetime(6) NULL DEFAULT NULL COMMENT '系统创建时间',
  `update_time` datetime(6) NULL DEFAULT NULL COMMENT '系统更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '民意征集表' ROW_FORMAT = DYNAMIC;

