-- ----------------------------
-- Table structure for biz_public_pol_interpret
-- ----------------------------
DROP TABLE IF EXISTS `biz_public_pol_interpret`;
CREATE TABLE `biz_public_pol_interpret`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `interpret_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '解读ID，唯一编码，UUID生成',
  `interpret_title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '解读标题，含政策名称，如“2025人才补贴政策解读”',
  `pol_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '政策文号，关联政策的官方文号，如“XX人社〔2025〕12号”，政策文件表（biz_public_pol）',
  `pol_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '政策名称，与政策文号同步，政策文件表（biz_public_pol）',
  `interpret_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '解读内容，分点拆解政策，支持图文',
  `publish_department_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '发布部门编码，发布解读的部门编码，部门信息表（sys_org）',
  `publish_department_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '发布部门名称，与部门编码同步，部门信息表（sys_org）',
  `publish_user_id` bigint NOT NULL COMMENT '发布人ID，发布人ID，用户表（sys_user）',
  `publish_time` datetime(3) NOT NULL COMMENT '发布时间，系统自动生成',
  `interpret_status` tinyint NOT NULL COMMENT '解读状态：1=草稿，2=已发布，3=已下架，控制展示状态',
  `effective_time` datetime(3) NOT NULL COMMENT '生效时间，解读生效时间',
  `attach_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '附件路径，政策原文附件路径',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注，补充说明，如“配套XX政策使用”',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段1，预留，标识政策领域，如社保/人才',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段2，预留，标识解读类型，如图文/视频',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段1，预留，存储视频解读链接',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段2，预留，存储政策原文链接',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  `create_time` datetime(6) NULL DEFAULT NULL COMMENT '系统创建时间',
  `update_time` datetime(6) NULL DEFAULT NULL COMMENT '系统更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '政策解读发布表' ROW_FORMAT = DYNAMIC;

