-- ----------------------------
-- Table structure for biz_public_snap_shot
-- ----------------------------
DROP TABLE IF EXISTS `biz_public_snap_shot`;
CREATE TABLE `biz_public_snap_shot`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `snap_shot_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '随手拍ID，唯一编码，UUID生成',
  `snap_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '记录单号，格式“SP+YYYYMMDD+6位流水号”',
  `problem_type_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '问题类型编码，问题类型，如“路灯故障”，字典表（sys_dict）',
  `problem_type_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '问题类型名称，与类型编码同步，字典表（sys_dict）',
  `coord_x` decimal(15, 2) NOT NULL COMMENT '事发坐标X，GPS定位经度（2000国家大地坐标系），单位：度，空间数据表（sys_spatial）',
  `coord_y` decimal(15, 2) NOT NULL COMMENT '事发坐标Y，GPS定位纬度，单位：度，空间数据表（sys_spatial）',
  `area_code` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '事发区域编码，由坐标反查生成，区域表（sys_area）',
  `area_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '事发区域名称，与区域编码同步，区域表（sys_area）',
  `problem_desc` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '问题描述，补充问题详情',
  `media_path` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '媒体路径，照片/视频存储路径（多个用逗号分隔）',
  `media_type` tinyint NOT NULL COMMENT '媒体类型：1=照片，2=视频，标识媒体类型',
  `rpt_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '上报人姓名',
  `rpt_phone` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '上报人电话，加密存储',
  `handle_status` tinyint NOT NULL COMMENT '处置状态：1=待处置，2=处置中，3=已办结，4=无效，流程状态',
  `handle_result` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '处置结果，处置完成后填写',
  `rpt_time` datetime(3) NOT NULL COMMENT '上报时间，系统自动生成',
  `finish_time` datetime(3) NULL DEFAULT NULL COMMENT '办结时间，处置完成时间',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段1，预留，标识问题等级，如轻微/严重',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段2，预留，标识媒体数量，如1张/多张',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段1，预留，存储定位精度',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段2，预留，存储处置人员ID',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  `create_time` datetime(6) NULL DEFAULT NULL COMMENT '系统创建时间',
  `update_time` datetime(6) NULL DEFAULT NULL COMMENT '系统更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '随手拍数据表' ROW_FORMAT = DYNAMIC;

