-- ----------------------------
-- Table structure for biz_public_svc_info
-- ----------------------------
DROP TABLE IF EXISTS `biz_public_svc_info`;
CREATE TABLE `biz_public_svc_info`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `svc_info_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '服务信息ID，唯一编码，UUID生成',
  `svc_title` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '服务标题，明确服务类型，如“XX公交3路站点调整”',
  `svc_type_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '服务类型编码，服务分类编码，如“交通”“医疗”，字典表（sys_dict）',
  `svc_type_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '服务类型名称，与类型编码同步，字典表（sys_dict）',
  `svc_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '服务内容，服务详情，如调整后的站点列表',
  `svc_provider` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '服务提供单位，提供服务的单位，如“XX公交公司”',
  `contact_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '联系电话，服务咨询电话，加密存储',
  `effective_time` datetime(3) NOT NULL COMMENT '生效时间，服务信息生效时间',
  `expire_time` datetime(3) NOT NULL COMMENT '失效时间，服务信息失效时间',
  `publish_user_id` bigint NOT NULL COMMENT '发布人ID，发布人ID，用户表（sys_user）',
  `publish_time` datetime(3) NOT NULL COMMENT '发布时间，系统自动生成',
  `info_status` tinyint NOT NULL COMMENT '信息状态：1=草稿，2=已发布，3=已过期，控制展示',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注，补充说明，如“临时调整，有效期1个月”',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段1，预留，标识服务级别，如常规/临时',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段2，预留，标识服务区域，如全市/某区',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段1，预留，存储服务地点，如“XX医院门诊楼”',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段2，预留，存储服务时间，如“每日8:00-17:00”',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  `create_time` datetime(6) NULL DEFAULT NULL COMMENT '系统创建时间',
  `update_time` datetime(6) NULL DEFAULT NULL COMMENT '系统更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '服务信息发布表' ROW_FORMAT = DYNAMIC;

