-- ----------------------------
-- Table structure for biz_res_match_schedule
-- ----------------------------
DROP TABLE IF EXISTS `biz_res_match_schedule`;
CREATE TABLE `biz_res_match_schedule`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `res_schedule_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '调度ID，唯一编码，UUID生成',
  `rel_scheme_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联方案ID，关联决策方案表的方案ID，决策方案表（biz_decision_scheme）',
  `rel_scheme_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联方案名称，与方案ID同步，决策方案表（biz_decision_scheme）',
  `res_demand_detail` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '资源需求明细，JSON格式存储资源需求（如[{\"res_type_id\":\"id1\",\"res_type_name\":\"传感器\",\"demand_count\":3}]），资源类型表（sys_res_type）',
  `matched_res_detail` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '匹配资源明细，JSON格式存储匹配结果（如[{\"res_id\":\"id1\",\"res_name\":\"传感器-001\",\"allocate_count\":1}]），资源信息表（biz_res_info）',
  `schedule_status` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '调度状态：待匹配/匹配中/匹配成功/匹配失败/调度完成，标识调度进度',
  `match_fail_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '匹配失败原因，调度状态为“匹配失败”时必填（如“传感器库存仅2台，需求3台”）',
  `schedule_wo_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '调度工单ID，关联资源调度工单表的工单ID，资源调度工单表（biz_res_schedule_wo）',
  `schedule_user` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '调度人，发起调度的用户ID，用户信息表（sys_user）',
  `schedule_time` datetime NOT NULL COMMENT '调度时间，格式：yyyy-MM-dd HH:mm:ss',
  `complete_time` datetime NULL DEFAULT NULL COMMENT '完成时间，格式：yyyy-MM-dd HH:mm:ss，调度状态为“调度完成”时必填',
  `res_mngr` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '资源负责人，资源管理负责人ID，用户信息表（sys_user）',
  `res_mngr_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '资源负责人姓名，与负责人ID同步，用户信息表（sys_user）',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段1，预留，如“调度批次”',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段2，预留，如“调度批次”',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段1，预留，存储资源使用期限',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段2，预留，存储资源使用期限',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 20 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '资源匹配调度表' ROW_FORMAT = DYNAMIC;

