-- ----------------------------
-- Table structure for biz_risk_hazard
-- ----------------------------
DROP TABLE IF EXISTS `biz_risk_hazard`;
CREATE TABLE `biz_risk_hazard`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `hazard_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '风险隐患ID',
  `hazard_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '风险隐患名称',
  `hazard_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '风险隐患的类型，如危险源/灾害隐患等',
  `risk_level` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '风险等级（低/中/高）',
  `warn_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '0' COMMENT '隐患的预警状态（0 未整改 / 1 整改中 / 2 已整改 / 3 已验收）',
  `rectify_deadline` datetime NULL DEFAULT NULL COMMENT '整改期限（格式：yyyy-MM-dd HH:mm:ss）',
  `region_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '行政区划编码，关联sys_area.region_code',
  `region_full_code` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '完整行政区划代码（12位）',
  `discover_time` datetime NULL DEFAULT NULL COMMENT '发现时间',
  `coord_x` decimal(10, 6) NULL DEFAULT NULL COMMENT '纬度(地图坐标)',
  `coord_y` decimal(10, 6) NULL DEFAULT NULL COMMENT '经度(地图坐标)',
  `update_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间，记录被修改时自动更新',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_risk_level`(`risk_level` ASC) USING BTREE,
  INDEX `idx_region_code`(`region_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 31 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '风险隐患信息表' ROW_FORMAT = DYNAMIC;

