-- ----------------------------
-- Table structure for biz_scene_map_config
-- ----------------------------
DROP TABLE IF EXISTS `biz_scene_map_config`;
CREATE TABLE `biz_scene_map_config`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `scene_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '所属场景唯一标识码（sceneKey）',
  `default_icon_width` int NULL DEFAULT NULL COMMENT '默认图标宽度',
  `default_icon_height` int NULL DEFAULT NULL COMMENT '默认图标高度',
  `default_icon_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '默认图标地址（未命中状态图标时使用）',
  `show_flag` tinyint NULL DEFAULT 1 COMMENT '是否显示图例：1显示，0不显示',
  `position` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '图例位置（如 bottomRight、bottomLeft）',
  `center_lat` decimal(10, 6) NULL DEFAULT NULL COMMENT '地图中心纬度（WGS84）',
  `center_lng` decimal(10, 6) NULL DEFAULT NULL COMMENT '地图中心经度（WGS84）',
  `rotate_speed` decimal(5, 2) NULL DEFAULT NULL COMMENT '旋转速度（数值越小越慢）',
  `loop_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '循环次数（infinity 表示无限循环，数字表示具体次数）',
  `pitch` int NULL DEFAULT NULL COMMENT '俯仰角（控制 3D 效果）',
  `zoom` int NULL DEFAULT NULL COMMENT '地图缩放级别',
  `center_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '中心点类型（复用地图中心坐标 / 自定义中心点）',
  `custom_center_lat` decimal(10, 6) NULL DEFAULT NULL COMMENT '自定义中心点纬度（center_type 为自定义时生效）',
  `custom_center_lng` decimal(10, 6) NULL DEFAULT NULL COMMENT '自定义中心点经度（center_type 为自定义时生效）',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '更新者',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分类扩展字段1',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分类扩展字段2',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '通用扩展字段1',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '通用扩展字段2',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '场景地图整体配置表' ROW_FORMAT = DYNAMIC;

