-- ----------------------------
-- Table structure for biz_task_overall_mng
-- ----------------------------
DROP TABLE IF EXISTS `biz_task_overall_mng`;
CREATE TABLE `biz_task_overall_mng`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `overall_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '统筹ID，唯一编码，采用UUID生成',
  `task_no` char(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '任务编号，关联调度指令/跨域协调编号，如“CMD_DISP2025000001”',
  `task_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '任务名称，如“XX内涝救援冲锋舟调度”',
  `task_type` char(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '任务类型：物资调度/队伍调度/车辆调度/设备调度/跨域协调，标识任务类型',
  `plan_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关联方案ID，关联调度方案表（biz_dispatch_plan）',
  `command_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关联指令ID，关联调度指令表（biz_dispatch_command）',
  `cross_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关联跨域ID，关联跨域调度协调表（biz_cross_region_dispatch）',
  `task_status` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '任务状态：待执行/执行中/已完成/已取消/超时，根据关联表状态同步',
  `priority` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '优先级：高/中/低，按事件等级设定（特急→高，紧急→中，一般→低）',
  `charger_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '任务负责人账号，关联用户信息表（sys_user）',
  `charger_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '任务负责人姓名，与负责人ID同步，关联用户信息表（sys_user）',
  `plan_complete_time` datetime NOT NULL COMMENT '计划完成时间，格式：yyyy-MM-dd HH:mm:ss',
  `actual_complete_time` datetime NULL DEFAULT NULL COMMENT '实际完成时间，格式：yyyy-MM-dd HH:mm:ss，已完成时必填',
  `delay_endure` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '延迟时长，如“30分钟”“2小时”，超时任务填写',
  `create_time` datetime NOT NULL COMMENT '创建时间，格式：yyyy-MM-dd HH:mm:ss，系统自动生成',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段1，预留，如“任务来源(本地/跨域)”',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段2，预留，如“任务来源(本地/跨域)”',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段1，预留，存储任务关联文档路径',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段2，预留，存储任务关联文档路径',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '任务统筹管理表' ROW_FORMAT = DYNAMIC;

