-- ----------------------------
-- Table structure for biz_typical_scenario_case
-- ----------------------------
DROP TABLE IF EXISTS `biz_typical_scenario_case`;
CREATE TABLE `biz_typical_scenario_case`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `typical_case_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '案例ID，唯一编码，UUID生成',
  `case_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '案例名称，如“2025年XX区域燃气泄漏事件优化案例”',
  `rel_scheme_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联方案ID，关联决策方案表的方案ID，决策方案表（biz_decision_scheme）',
  `rel_eval_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联评估ID，关联决策效果评估表的评估ID，决策效果评估表（biz_decision_effect_eval）',
  `case_tags` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '案例标签，逗号分隔的标签（如“燃气/应急处置/传感器部署”）',
  `applicable_scenario` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '适用场景，案例适用的业务场景（如“城市燃气管道泄漏事件处置优化”）',
  `core_measures` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '核心措施，案例的核心实施措施（分点描述），决策方案表（biz_decision_scheme）',
  `resource_input` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '资源投入，如“传感器3台（8万元）、人员2名（5万元）”，决策方案表（biz_decision_scheme）',
  `implementation_effect` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '实施效果，如“事件下降55%，响应时长缩短至18分钟”，决策效果评估表（biz_decision_effect_eval）',
  `eval_grade` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '评估等级：优秀/良好/合格/不合格，取自决策效果评估表，决策效果评估表（biz_decision_effect_eval）',
  `success_exp` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '成功经验，案例的成功做法（取自评估表），决策效果评估表（biz_decision_effect_eval）',
  `improve_suggs` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '改进建议，案例的优化建议（取自优化建议表），决策优化建议表（biz_decision_opt_sugg）',
  `arch_user` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '归档人，案例归档人ID，用户信息表（sys_user）',
  `arch_time` datetime NOT NULL COMMENT '归档时间，格式：yyyy-MM-dd HH:mm:ss',
  `case_status` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '案例状态：已归档/已下架，标识案例是否可用',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段1，预留，如“案例来源”',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段2，预留，如“案例来源”',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段1，预留，存储案例附件链接',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段2，预留，存储案例附件链接',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '典型场景案例库表' ROW_FORMAT = DYNAMIC;

