INSERT INTO `biz_typical_scenario_case` VALUES (3, '10', '2025年XX区域燃气泄漏事件优化案例', 'scheme_001', 'eval_001', '燃气/应急处置/传感器', '城市燃气管道泄漏', '1. 快速隔离泄漏区域\n2. 启动应急疏散预案\n3. 协调维修团队进场', '传感器3台（8万元）、人员2名（5万元）', '事件下降55%，响应时长缩短至18分钟', '优先', '多部门协同响应机制有效', '建议增加备用传感器数量', 'user001', '2024-01-15 10:30:00', '已归档', '内部案例', NULL, NULL, NULL, 'admin', 'admin', b'0', 1, '2025-12-23 16:12:43', '2025-12-23 16:12:43', '2025-12-23 16:12:43', '2025-12-23 16:12:43');
INSERT INTO `biz_typical_scenario_case` VALUES (4, '11', '2025年工业园区化学品泄露处置案例', 'scheme_002', 'eval_002', '化工/危险品/环境监测', '工业危险品管理', '1. 建立安全隔离带\n2. 启动环境监测\n3. 组织专业处置团队', '防护设备5套（15万元）、监测仪器2台（12万元）', '污染范围减少70%，处置时间缩短40%', '良好', '快速的环境监测与评估', '建议建立专用处置物资储备库', 'user002', '2024-02-20 14:25:00', '已归档', '合作单位提供', NULL, NULL, NULL, 'admin', 'admin', b'0', 1, '2025-12-23 16:12:43', '2025-12-23 16:12:43', '2025-12-23 16:12:43', '2025-12-23 16:12:43');
INSERT INTO `biz_typical_scenario_case` VALUES (5, '12', '2024年城市内涝应急排水案例', 'scheme_003', 'eval_003', '城市/防汛/排水', '城市防洪排涝', '1. 启动排水泵站\n2. 组织抢险队伍\n3. 协调交通管制', '排水设备8台（25万元）、抢险人员15名', '排水效率提升60%，恢复通行时间缩短50%', '良好', '多部门联动响应迅速', '建议增加移动排水设备配置', 'user003', '2024-03-10 09:15:00', '已归档', '政府合作项目', NULL, NULL, NULL, 'admin', 'admin', b'0', 1, '2025-12-23 16:12:43', '2025-12-23 16:12:43', '2025-12-23 16:12:43', '2025-12-23 16:12:43');
INSERT INTO `biz_typical_scenario_case` VALUES (6, '13', '2025年电梯困人应急救援案例', 'scheme_004', 'eval_004', '特种设备/救援/安全', '特种设备安全', '1. 安抚被困人员情绪\n2. 启动专业救援程序\n3. 检查设备故障原因', '救援设备3套（6万元）、专业技术人员4名', '平均救援时间缩短至12分钟，用户满意度达98%', '优先', '专业救援队伍响应及时', '建议建立电梯故障预警系统', 'user004', '2024-04-05 16:40:00', '已归档', '物业公司提供', NULL, NULL, NULL, 'admin', 'admin', b'0', 1, '2025-12-23 16:12:43', '2025-12-23 16:12:43', '2025-12-23 16:12:43', '2025-12-23 16:12:43');
INSERT INTO `biz_typical_scenario_case` VALUES (7, '14', '2025年大型活动医疗保障案例', 'scheme_005', 'eval_005', '公共安全/医疗/应急', '公共活动医疗保障', '1. 设立医疗站点\n2. 配置急救人员\n3. 建立绿色通道', '医疗设备10套（30万元）、医护人员20名', '医疗处置及时率100%，未发生重大医疗事件', '优秀', '医疗资源配置合理有效', '建议增加应急医疗培训频次', 'user005', '2024-05-12 11:20:00', '已归档', '卫生部门合作', NULL, NULL, NULL, 'admin', 'admin', b'0', 1, '2025-12-23 16:12:43', '2025-12-23 16:12:43', '2025-12-23 16:12:43', '2025-12-23 16:12:43');

-- ----------------------------
-- Table structure for biz_unit_grid_attr
-- ----------------------------
DROP TABLE IF EXISTS `biz_unit_grid_attr`;
CREATE TABLE `biz_unit_grid_attr`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `unit_attr_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '属性ID',
  `unit_grid_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '单元网格ID',
  `unit_grid_code` char(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '单元网格编码',
  `area` int NOT NULL COMMENT '面积(m²)',
  `init_time` datetime NOT NULL COMMENT '初始时间',
  `end_time` datetime NULL DEFAULT NULL COMMENT '终止时间',
  `remark` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '备注',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段1',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段2',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段1',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段2',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '单元网格属性表' ROW_FORMAT = DYNAMIC;

