-- ----------------------------
-- Table structure for biz_warn
-- ----------------------------
DROP TABLE IF EXISTS `biz_warn`;
CREATE TABLE `biz_warn`  (
  `warn_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '预警ID，唯一标识',
  `warn_type` int NOT NULL COMMENT '预警类型，取值范围0-食药安全/1-特种设备/2-市场秩序等，关联biz_warn_type表',
  `warn_level` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '风险等级，高/中/低',
  `warn_status` int NOT NULL COMMENT '预警状态，0-待处置，1-已解除等',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间，记录预警生成时间',
  `relieve_time` datetime NULL DEFAULT NULL COMMENT '解除时间，仅已解除预警必填',
  `region_full_code` char(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '区域编码，12位行政区域码，关联sys_area表',
  PRIMARY KEY (`warn_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

