-- ----------------------------
-- Table structure for biz_wo
-- ----------------------------
DROP TABLE IF EXISTS `biz_wo`;
CREATE TABLE `biz_wo`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '工单ID',
  `wo_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '工单编号',
  `mng_comp_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '设施ID，关联 biz_mng_comp.mng_comp_id',
  `comp_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '设施名称，从 biz_mng_comp 的 comp_name 冗余一份',
  `status` int NULL DEFAULT 0 COMMENT '状态：0未开始 1处理中 2已完成',
  `dept_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '责任部门代码',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '抢修工单表' ROW_FORMAT = DYNAMIC;

