-- ----------------------------
-- Table structure for gc_biz_mng_comp
-- ----------------------------
DROP TABLE IF EXISTS `gc_biz_mng_comp`;
CREATE TABLE `gc_biz_mng_comp`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `mng_comp_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '部件ID，唯一编码，UUID生成',
  `comp_code` char(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '部件标识码，格式6位行政码+2位大类码+3位小类码+5位顺序码，唯一',
  `comp_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '部件名称，关联小类名称+位置，如“XX路电力井盖”，关联管理部件小类表(gc_biz_mng_comp_minor)',
  `minor_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联管理部件小类ID，关联管理部件小类表(gc_biz_mng_comp_minor)',
  `minor_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联管理部件小类名称，与小类ID同步，不可改，关联管理部件小类表(gc_biz_mng_comp_minor)',
  `dept_code` char(18) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主管部门代码，主管部门信用代码，关联部门信息表(sys_org)',
  `dept_name` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主管部门名称，与部门代码同步，关联部门信息表(sys_org)',
  `grid_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联单元网格ID，关联网格信息表(biz_grid_info)',
  `grid_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联单元网格名称，与网格ID同步，关联网格信息表(biz_grid_info)',
  `comp_status` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '部件状态，如完好/破损/丢失/废弃，关联部件状态字典表(sys_dict_mng_comp_state)',
  `init_date` date NOT NULL COMMENT '部件普查日期，格式YYYYMMDD',
  `change_date` date NULL DEFAULT NULL COMMENT '状态/权属变更时更新日期，格式YYYYMMDD',
  `data_source` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '数据来源，如实测/人工上报/普查，关联数据来源字典表(sys_dict_data_source)',
  `create_user` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '录入人账号，关联用户信息表(sys_user)',
  `create_time` datetime NOT NULL COMMENT '系统生成，格式yyyy - MM - dd HH:mm:ss',
  `update_user` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '修改人账号，关联用户信息表(sys_user)',
  `update_time` datetime NULL DEFAULT NULL COMMENT '系统生成，格式yyyy - MM - dd HH:mm:ss',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段1，预留，如“部件材质”',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段2，预留，如“部件材质”',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段1，预留，如“安装时间”',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段2，预留，如“安装时间”',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '管理部件表' ROW_FORMAT = DYNAMIC;

