-- ----------------------------
DROP TABLE IF EXISTS `gc_biz_mng_comp_spatial`;
CREATE TABLE `gc_biz_mng_comp_spatial`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `mng_comp_spatial_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '空间数据ID，唯一编码，UUID生成',
  `mng_comp_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联管理部件ID，一对一，关联管理部件表(gc_biz_mng_comp)',
  `comp_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联部件名称，与部件ID同步，不可改，关联管理部件表(gc_biz_mng_comp)',
  `coord_system` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '2000国家大地坐标系' COMMENT '坐标系类型，固定，符合国标，2000国家大地坐标系',
  `coord_x` decimal(15, 2) NOT NULL COMMENT '坐标X，经度，保留2位小数，范围 - 180.00至180.00',
  `coord_y` decimal(15, 2) NOT NULL COMMENT '坐标Y，纬度，保留2位小数，范围 - 90.00至90.00',
  `elevation` decimal(10, 3) NULL DEFAULT NULL COMMENT '高程，可选，米，1985国家高程基准，保留3位小数',
  `accuracy` decimal(6, 2) NOT NULL COMMENT '定位精度，米，±0.5/±1.0/±10.0，定位精度等级对应的误差',
  `accuracy_level` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '定位精度等级，A/B/C，A类±0.5m、B类±1.0m、C类±10.0m',
  `survey_unit` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '测绘单位，测绘实施单位',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '管理部件空间数据表' ROW_FORMAT = DYNAMIC;

