  `matter_major_code` char(2) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '大类代码，2位字符，01 - 99，顺序编排，同一系统唯一，符合GB/T 30428.2',
  `matter_major_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '大类名称，如市容环境/宣传广告等，国标名称，扩展大类加“（自定义）”',
  `matter_major_desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '大类说明，描述大类覆盖事项范围，如“宣传广告：含违规广告、招牌破损”',
  `sort_num` int NULL DEFAULT NULL COMMENT '排序序号，1 - 999，列表展示优先级，数值越小越靠前',
  `enable_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '1' COMMENT '启用状态，1（启用）/0（禁用），默认1，禁用后关联小类同步禁用',
  `create_user` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '创建人，配置人账号，关联用户信息表(sys_user)',
  `create_time` datetime NOT NULL COMMENT '创建时间，系统生成，格式yyyy - MM - dd HH:mm:ss',
  `update_user` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人，修改人账号，关联用户信息表(sys_user)',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间，系统生成，格式yyyy - MM - dd HH:mm:ss',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '管理事项大类表' ROW_FORMAT = DYNAMIC;

