-- ----------------------------
-- Table structure for gc_local_regulation_info
-- ----------------------------
DROP TABLE IF EXISTS `gc_local_regulation_info`;
CREATE TABLE `gc_local_regulation_info`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `regulation_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '法规ID，唯一编码，采用UUID',
  `regulation_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '法规编号，如\"XX省人民政府令〔2025〕XX号\"',
  `regulation_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '法规完整名称',
  `regulation_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '法规类型，政府规章/地方性法规/规范性文件',
  `admin_code` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '所属行政区划代码，符合GB/T 2260',
  `admin_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '所属行政区划名称',
  `issue_dept` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '发布单位，如\"XX省人民政府\"\"XX市人大常委会\"',
  `issue_time` datetime NULL DEFAULT NULL COMMENT '发布时间，格式：yyyy-MM-dd HH:mm:ss',
  `effective_time` date NULL DEFAULT NULL COMMENT '生效时间，格式：yyyy-MM-dd',
  `expire_time` date NULL DEFAULT NULL COMMENT '失效时间，格式：yyyy-MM-dd，永久有效则为空',
  `revision_basis` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '修订依据，如\"根据《XX国家政策》修订\"',
  `related_national_policy_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关联依据的国家政策ID',
  `regulation_file_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'PDF格式原文存储路径',
  `regulation_abstract` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '法规核心内容摘要',
  `regulation_status` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '法规状态，未生效/有效/已修订/已废止',
  `upload_user_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '上传管理员账号',
  `upload_time` datetime NULL DEFAULT NULL COMMENT '上传时间，格式：yyyy-MM-dd HH:mm:ss',
  `update_user_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '修改管理员账号',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间，格式：yyyy-MM-dd HH:mm:ss',
  `extend_category` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '扩展分类字段，预留用于自定义标签',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '地方法规信息表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of gc_local_regulation_info
-- ----------------------------

