-- ----------------------------
-- Table structure for gc_result_publicity
-- ----------------------------
DROP TABLE IF EXISTS `gc_result_publicity`;
CREATE TABLE `gc_result_publicity`  (
  `publicity_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '公示ID，唯一编码，采用UUID',
  `publicity_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '公示名称，如\"2024年上半年城市运行监测评价结果公示\"',
  `eval_task_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '关联任务ID，关联的评价任务唯一标识',
  `task_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '任务名称，从评价任务表自动同步',
  `publicity_scope` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '公示范围，如\"全市公开\"\"部门内部公开\"',
  `publicity_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '公示的具体内容，如各领域得分、排名、主要问题',
  `publicity_channel` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '公示渠道，如\"平台公示栏、政府官网、公众号\"',
  `publicity_start_time` timestamp NOT NULL COMMENT '公示开始时间，格式：yyyy-MM-dd HH:mm:ss',
  `publicity_end_time` timestamp NOT NULL COMMENT '公示截止时间，格式：yyyy-MM-dd HH:mm:ss',
  `publicity_status` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '公示状态：未公示/公示中/已结束',
  `publicity_attachment` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '公示详情附件存储路径（如PDF报告）',
  `create_by` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '记录创建操作人员姓名',
  `create_time` timestamp NOT NULL COMMENT '创建时间，格式：yyyy-MM-dd HH:mm:ss',
  PRIMARY KEY (`publicity_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '结果公示表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of gc_result_publicity
-- ----------------------------

-- ----------------------------
-- Table structure for gc_result_push
-- ----------------------------
DROP TABLE IF EXISTS `gc_result_push`;
CREATE TABLE `gc_result_push`  (
  `push_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '推送ID，唯一编码，采用UUID',
  `eval_task_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '关联任务ID，关联的评价任务唯一标识',
  `task_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '任务名称，从评价任务表自动同步',
  `eval_domain` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '评价领域，如\"房屋建筑\"\"智慧农业\"',
  `push_target_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '推送对象类型，部门/系统/个人',
  `push_target_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '推送对象ID，部门ID/系统对接ID/用户ID',
  `push_target_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '推送对象名称，如\"XX区住建局\"\"绩效考核系统\"',
  `push_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '推送内容，包含结果得分、排名、问题清单、整改建议等',
  `push_method` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '推送方式，平台消息/API接口/邮件/短信',
  `push_time` timestamp NOT NULL COMMENT '推送时间，格式：yyyy-MM-dd HH:mm:ss',
  `push_status` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '推送状态，待推送/推送成功/推送失败',
  `fail_reason` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '失败原因，如\"接口超时\"\"用户不存在\"',
  `feedback_status` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '反馈状态，未反馈/已反馈',
  `feedback_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '反馈内容，推送对象的接收确认或整改计划',
  `push_by` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '推送人，记录推送操作人员姓名',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`push_id`) USING BTREE,
  INDEX `idx_eval_task_id`(`eval_task_id` ASC) USING BTREE,
  INDEX `idx_push_target_type`(`push_target_type` ASC) USING BTREE,
  INDEX `idx_push_target_id`(`push_target_id` ASC) USING BTREE,
  INDEX `idx_push_status`(`push_status` ASC) USING BTREE,
  INDEX `idx_feedback_status`(`feedback_status` ASC) USING BTREE,
  INDEX `idx_push_time`(`push_time` ASC) USING BTREE,
  INDEX `idx_push_by`(`push_by` ASC) USING BTREE,
  INDEX `idx_eval_domain`(`eval_domain` ASC) USING BTREE,
  INDEX `idx_push_method`(`push_method` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '结果推送表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of gc_result_push
-- ----------------------------

-- ----------------------------
-- Table structure for gc_risk_type
-- ----------------------------
DROP TABLE IF EXISTS `gc_risk_type`;
CREATE TABLE `gc_risk_type`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `risk_type_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '风险类型ID',
  `risk_type_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '风险类型名称',
  `risk_code` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '风险编码',
  `domain_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所属分域ID',
  `domain_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '所属分域名称',
  `risk_desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '风险描述',
  `response_measures` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '应对措施',
  `enable_status` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '启用状态',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_risk_type_id`(`risk_type_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '风险类型库管理' ROW_FORMAT = DYNAMIC;

