INSERT INTO `gc_risk_type` VALUES (4, 'RT-SRHW-001', '垃圾堆积超标', 'SRHW001', 'SRHW', '市容环卫', '公共区域垃圾清运不及时造成堆积', '增加临时清运力量，优化清运频次与路线', '启用', 'system', 'system', b'0', 1, '2024-10-01 11:00:00', '2024-10-01 11:00:00');
INSERT INTO `gc_risk_type` VALUES (5, 'RT-YLHH-001', '绿化枯萎异常', 'YLHH001', 'YLHH', '园林绿化', '持续干旱或病虫害导致绿化枯萎', '补水养护，施肥防治，必要时更换植株', '启用', 'system', 'system', b'0', 1, '2024-10-01 12:00:00', '2024-10-01 12:00:00');
