-- ----------------------------
-- Table structure for gen_park_guidance
-- ----------------------------
DROP TABLE IF EXISTS `gen_park_guidance`;
CREATE TABLE `gen_park_guidance`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '记录唯一标识',
  `guidance_id` bigint NOT NULL COMMENT '停车诱导业务唯一标识',
  `user_id` bigint NOT NULL COMMENT '用户唯一标识',
  `user_pos_x` decimal(10, 6) NULL DEFAULT NULL COMMENT '用户当前位置X坐标',
  `user_pos_y` decimal(10, 6) NULL DEFAULT NULL COMMENT '用户当前位置Y坐标',
  `recommend_park_id` bigint NOT NULL COMMENT '推荐的停车场唯一标识',
  `recommend_park_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '推荐的停车场名称',
  `remain_berths` int NULL DEFAULT NULL COMMENT '推荐停车场剩余泊位数量',
  `est_drive_time` int NULL DEFAULT NULL COMMENT '到达推荐停车场的预计行驶时间（秒）',
  `charge_std` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '推荐停车场收费标准',
  `guidance_method` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '停车诱导采用的方式',
  `guidance_time` datetime NULL DEFAULT NULL COMMENT '执行停车诱导的时间',
  `user_behavior` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '用户在诱导过程中的行为记录',
  `create_time` datetime NULL DEFAULT NULL COMMENT '业务记录创建时间',
  `region_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '所属行政区划名称',
  `grid_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '所属网格名称',
  `matter_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '关联的管理事项名称',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '记录创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '记录更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '记录最后更新时间',
  `deleted` tinyint(1) NULL DEFAULT 0 COMMENT '删除状态标识',
  `tenant_id` bigint NULL DEFAULT NULL COMMENT '租户唯一标识',
  `ext_cat1` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分类扩展字段1',
  `ext_cat2` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分类扩展字段2',
  `ext_common1` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '通用扩展字段1',
  `ext_common2` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '通用扩展字段2',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '停车诱导服务表' ROW_FORMAT = DYNAMIC;

