-- Table structure for stat_app_scene_rpt
-- ----------------------------
DROP TABLE IF EXISTS `stat_app_scene_rpt`;
CREATE TABLE `stat_app_scene_rpt`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `region_full_code` char(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '统计区域12位地区码（GB/T 2260）',
  `stat_time` datetime NOT NULL COMMENT '统计时间',
  `type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '资源类型，如自然景观、历史古迹、主题公园',
