-- Table structure for stat_early_warn_time
-- ----------------------------
DROP TABLE IF EXISTS `stat_early_warn_time`;
CREATE TABLE `stat_early_warn_time`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `time_stat_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '统计ID',
  `time_dimension` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '统计维度',
  `stat_cycle_value` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '统计周期值',
  `stat_cycle_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '统计周期名称',
  `total_warn_count` int NOT NULL COMMENT '预警总数',
  `main_warn_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '主要预警类型',
  `main_type_count` int NULL DEFAULT NULL COMMENT '主要预警类型数量',
  `completed_count` int NOT NULL COMMENT '已办结数',
  `handle_rate` decimal(5, 2) NOT NULL COMMENT '处置率',
  `stat_user_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '统计人',
  `stat_time` datetime NOT NULL COMMENT '统计时间',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段1',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段2',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段1',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段2',
  `creator` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'creator',
  `updater` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'updater',
  `deleted` tinyint NULL DEFAULT 0 COMMENT 'deleted',
  `tenant_id` bigint NULL DEFAULT NULL COMMENT 'tenant_id',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'create_time',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'update_time',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '预警告警时间维度统计表' ROW_FORMAT = DYNAMIC;

