-- Table structure for stat_early_warn_type
-- ----------------------------
DROP TABLE IF EXISTS `stat_early_warn_type`;
CREATE TABLE `stat_early_warn_type`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `type_stat_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '统计ID',
  `stat_cycle` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '统计周期',
  `warn_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预警类型',
  `warn_type_code` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预警类型编码',
  `total_warn_count` int NULL DEFAULT NULL COMMENT '预警总数',
  `proportion` decimal(5, 2) NULL DEFAULT NULL COMMENT '占比',
  `completed_count` int NULL DEFAULT NULL COMMENT '已办结数',
  `handle_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '处置率',
  `main_region_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '主要分布区域名称',
  `main_region_count` int NULL DEFAULT NULL COMMENT '主要分布区域数量',
  `stat_user_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '统计人',
  `stat_time` datetime NULL DEFAULT NULL COMMENT '统计时间',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段1',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段2',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段1',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段2',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '创建人',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人',
  `deleted` tinyint(1) NULL DEFAULT 0 COMMENT '是否删除',
  `tenant_id` bigint NULL DEFAULT NULL COMMENT '租户ID',
