-- Table structure for stat_emer_res_status
-- ----------------------------
DROP TABLE IF EXISTS `stat_emer_res_status`;
CREATE TABLE `stat_emer_res_status`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增主键ID',
  `stat_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '统计ID，唯一编码，UUID生成',
  `stat_cycle` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '统计周期，日/周/月，格式：YYYYMMDD（日）、YYYYQn（周）、YYYYMM（月）',
  `stat_time` datetime NOT NULL COMMENT '统计时间，格式yyyy - MM - dd HH:mm:ss，系统自动生成',
  `res_type` char(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '资源类型，应急物资/救援队伍/救援车辆/救援设备',
  `region_code` char(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '行政区划代码，关联行政区划表',
  `region_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '行政区划名称，与区域代码同步',
  `total_quantity` int NOT NULL COMMENT '总数量，该类型资源总数量',
  `available_quantity` int NOT NULL COMMENT '可用数量，正常状态资源数量',
  `abn_quantity` int NOT NULL COMMENT '异常数量，异常状态资源数量',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '资源状态统计表' ROW_FORMAT = DYNAMIC;

