  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `region_full_code` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '12位地区码',
  `stat_time` date NOT NULL COMMENT '统计时间',
  `infect_rpt_timely_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '传染病报告及时率(%)',
