DROP TABLE IF EXISTS `stat_health_public_metric`;
CREATE TABLE `stat_health_public_metric`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `region_full_code` varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '12位地区码',
  `stat_time` date NOT NULL COMMENT '统计时间',
  `family_doctor_sign_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '家庭医生签约率(%)',
  `vaccine_complete_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '疫苗接种完成率(%)',
  `std_value` decimal(5, 2) NULL DEFAULT NULL COMMENT '达标阈值(如90表示≥90%为达标)',
  `key_pop_follow_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '重点人群健康随访率(%)',
  `chronic_disease_mng_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '慢性病管理率(%)',
  `infect_rpt_timely_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '传染病报告及时率(%)',
  `public_health_qualified_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '公卫指标达标率(%)',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

