-- ----------------------------
-- Table structure for stat_law_enf_case
-- ----------------------------
DROP TABLE IF EXISTS `stat_law_enf_case`;
CREATE TABLE `stat_law_enf_case`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID，自增',
  `region_short_code` char(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '统计地区六位行政区划代码（省市县）',
  `stat_time` datetime NOT NULL COMMENT '统计时间（每日统计或周期汇总时间）',
  `total_case_count` int NULL DEFAULT 0 COMMENT '统计周期内总案件数',
  `new_case_today` int NULL DEFAULT 0 COMMENT '今日新增案件数',
  `today_completed_case` int NULL DEFAULT 0 COMMENT '今日办结案件数',
  `case_complete_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '案件办结率 (%) = 已办结案件数 / 总案件数',
  `case_overdue_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '案件超期率 (%) = 超期案件数 / 总案件数',
  `case_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '案件类型，如：违法建设、占道经营等',
  `case_source` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '案件来源，如：热线举报、巡查发现等',
  `progress_stage` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '案件办理进度阶段，如：调查取证、处罚告知、立案、归档',
  `case_count` int NULL DEFAULT 0 COMMENT '按类型/来源/进度统计对应案件数量',
  `overdue_case_count` int NULL DEFAULT 0 COMMENT '当前统计周期内超期未办结案件数',
  `total_overdue_case` int NULL DEFAULT 0 COMMENT '累计维度的超期案件总数',
  `today_new_overdue` int NULL DEFAULT 0 COMMENT '今日新增超期案件数',
  `punish_amount` decimal(10, 2) NULL DEFAULT NULL COMMENT '处罚金额总额（统计周期内）',
  `avg_case_handle_time` int NULL DEFAULT NULL COMMENT '平均办结时长（小时）',
  `repeat_rpt_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '重复举报率 (%)',
  `created_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '执法案件统计表（用于综合执法大屏全域概览与案件分布分析）' ROW_FORMAT = DYNAMIC;

