-- ----------------------------
-- Table structure for stat_law_enf_coop
-- ----------------------------
DROP TABLE IF EXISTS `stat_law_enf_coop`;
CREATE TABLE `stat_law_enf_coop`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `total_cross_region_event` int NULL DEFAULT 0 COMMENT '跨区域协同事件总数',
  `cross_region_complete_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '协同完成率（0-100）',
  `avg_cross_region_time` decimal(10, 2) NULL DEFAULT NULL COMMENT '平均协同时长（单位：天）',
  `today_new_cross_region` int NULL DEFAULT 0 COMMENT '今日新增协同事件数',
  `total_dept_joint_event` int NULL DEFAULT 0 COMMENT '部门联合事件总数',
  `dept_joint_complete_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '联合完成率（0-100）',
  `participating_dept_count` int NULL DEFAULT 0 COMMENT '参与部门数',
  `avg_dept_joint_time` decimal(10, 2) NULL DEFAULT NULL COMMENT '平均联合时长（单位：天）',
  `total_region_link_event` int NULL DEFAULT 0 COMMENT '区域联动事件总数',
  `region_link_complete_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '联动完成率（0-100）',
  `cross_dept_coop_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '跨部门协同率（0-100）',
  `cross_region_coop_count` int NULL DEFAULT 0 COMMENT '跨区协作次数',
  `avg_region_link_time` decimal(10, 2) NULL DEFAULT NULL COMMENT '平均联动时长（单位：天）',
  `joint_case_complete_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '协同案件办结率（0-100）',
  `law_object_satisfy` decimal(5, 2) NULL DEFAULT NULL COMMENT '执法对象满意度（0-100）',
  `repeatillegal_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '重复违法率（0-100）',
  `saved_time_by_coop` decimal(10, 2) NULL DEFAULT NULL COMMENT '协同执法节省时长（单位：小时）',
  `stat_time` datetime NOT NULL COMMENT '统计时间',
  `region_short_code` char(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '统计地区6位短码（省/市/县）',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '执法协同统计表' ROW_FORMAT = DYNAMIC;

