-- Table structure for stat_law_enf_std
-- ----------------------------
DROP TABLE IF EXISTS `stat_law_enf_std`;
CREATE TABLE `stat_law_enf_std`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `compliance_qualified_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '合规检查合格率（0-100）',
  `illegal_enf_count` int NULL DEFAULT 0 COMMENT '违规执法次数',
  `doc_std_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '执法文书规范率（0-100）',
  `train_complete_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '合规培训完成率（0-100）',
  `law_compliance_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '执法合规率（0-100）',
  `stat_time` datetime NOT NULL COMMENT '统计时间',
  `region_short_code` char(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '统计地区6位短码（省/市/县）',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '执法规范统计表' ROW_FORMAT = DYNAMIC;

