-- ----------------------------
-- Table structure for stat_mng_comp
-- ----------------------------
DROP TABLE IF EXISTS `stat_mng_comp`;
CREATE TABLE `stat_mng_comp`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `stat_mng_comp_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '统计ID，唯一编码，UUID生成',
  `stat_cycle` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '统计周期，如年/季/月，格式:YYYY/YYYYQn/YYYYMM',
  `stat_cycle_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '统计周期名称，如“2025年9月”',
  `area_code` char(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '行政区划代码，符合GB/T 2260，关联行政区划表(sys_area)',
  `area_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '行政区划名称，与代码同步，关联行政区划表(sys_area)',
  `comp_major_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '部件大类ID，关联管理部件大类ID，关联管理部件大类表(biz_mng_comp_major)',
  `comp_major_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '部件大类名称，与大类ID同步，关联管理部件大类表(biz_mng_comp_major)',
  `comp_minor_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '部件小类ID，关联管理部件小类ID（钻取时必填），关联管理部件小类表(biz_mng_comp_minor)',
  `comp_minor_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '部件小类名称，与小类ID同步，关联管理部件小类表(biz_mng_comp_minor)',
  `total_comp_count` int NULL DEFAULT NULL COMMENT '部件总数，该维度下部件总数，关联管理部件表(biz_mng_comp)',
  `normal_comp_count` int NULL DEFAULT NULL COMMENT '完好部件数，状态为“完好”的数量，关联管理部件表(biz_mng_comp)',
  `damaged_comp_count` int NULL DEFAULT NULL COMMENT '破损部件数，状态为“破损”的数量，关联管理部件表(biz_mng_comp)',
  `lost_comp_count` int NULL DEFAULT NULL COMMENT '丢失部件数，状态为“丢失”的数量，关联管理部件表(biz_mng_comp)',
  `discarded_comp_count` int NULL DEFAULT NULL COMMENT '废弃部件数，状态为“废弃”的数量，关联管理部件表(biz_mng_comp)',
  `new_comp_count` int NULL DEFAULT NULL COMMENT '新增部件数，统计周期内新增数量，关联管理部件表(biz_mng_comp)',
  `update_comp_count` int NULL DEFAULT NULL COMMENT '更新部件数，统计周期内更新数量，关联管理部件表(biz_mng_comp)',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 14 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '管理部件统计表' ROW_FORMAT = DYNAMIC;

