-- ----------------------------
-- Table structure for stat_mng_matter
-- ----------------------------
DROP TABLE IF EXISTS `stat_mng_matter`;
CREATE TABLE `stat_mng_matter`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `stat_mng_matter_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '统计ID，唯一编码，UUID生成',
  `stat_cycle` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '统计周期，如年/季/月，格式:YYYY/YYYYQn/YYYYMM',
  `stat_cycle_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '统计周期名称，如“2025年Q3”',
  `area_code` char(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '行政区划代码，符合GB/T 2260，关联行政区划表(sys_area)',
  `area_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '行政区划名称，与代码同步，关联行政区划表(sys_area)',
  `matter_major_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '事项大类ID，关联管理事项大类ID，关联管理事项大类表(biz_mng_matter_major)',
  `matter_major_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '事项大类名称，与大类ID同步，关联管理事项大类表(biz_mng_matter_major)',
  `matter_minor_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '事项小类ID，关联管理事项小类ID(钻取时必填)，关联管理事项小类表(biz_mng_matter_minor)',
  `matter_minor_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '事项小类名称，与小类ID同步，关联管理事项小类表(biz_mng_matter_minor)',
  `dept_code` char(18) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '处置部门代码，关联主管部门信用代码，关联部门信息表(sys_org)',
  `dept_name` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '处置部门名称，与部门代码同步，关联部门信息表(sys_org)',
  `total_rpt_count` int NULL DEFAULT NULL COMMENT '上报总数，统计周期内上报总数，关联管理事项表(biz_mng_matter)',
  `pend_count` int NULL DEFAULT NULL COMMENT '待处置数，状态为“待处置”的数量，关联管理事项表（biz_mng_matter）',
  `handl_count` int NULL DEFAULT NULL COMMENT '处置中数，状态为“处置中”的数量，关联管理事项表（biz_mng_matter）',
  `completed_count` int NULL DEFAULT NULL COMMENT '已办结数，状态为“已办结”的数量，关联管理事项表（biz_mng_matter）',
  `rejected_count` int NULL DEFAULT NULL COMMENT '已驳回数，状态为“已驳回”的数量，关联管理事项表（biz_mng_matter）',
  `complete_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '办结率，（已办结数/（上报总数 - 已驳回数））×100，关联管理事项表（biz_mng_matter）',
  `avg_handle_endure` decimal(10, 2) NULL DEFAULT NULL COMMENT '平均处置时长，已办结事项处置时长平均值，关联管理事项表（biz_mng_matter）',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 20 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '管理事项统计表' ROW_FORMAT = DYNAMIC;

