-- ----------------------------
-- Table structure for stat_mng_matter_rpt
-- ----------------------------
DROP TABLE IF EXISTS `stat_mng_matter_rpt`;
CREATE TABLE `stat_mng_matter_rpt`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增ID',
  `region_full_code` char(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '统计区域12位地区码（GB/T 2260）',
  `stat_time` datetime NOT NULL COMMENT '统计时间',
  `type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '投诉类型',
  `total_rpt_count` int NULL DEFAULT 0 COMMENT '投诉总数',
  `pend_count` int NULL DEFAULT 0 COMMENT '未办结投诉数',
  `complete_rate` double NULL DEFAULT 0 COMMENT '投诉办结率（%）',
  `avg_handle_endure` double NULL DEFAULT 0 COMMENT '服务响应时长（小时或分钟，根据实际）',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '投诉事项统计表，记录各区域各时间周期的投诉总量、未办结数及办结率等指标' ROW_FORMAT = DYNAMIC;

