-- ----------------------------
-- Table structure for stat_mon_comp_rpt
-- ----------------------------
DROP TABLE IF EXISTS `stat_mon_comp_rpt`;
CREATE TABLE `stat_mon_comp_rpt`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增主键ID',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time_sys` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time_sys` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  `stat_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '唯一编码，采用UUID生成',
  `stat_cycle` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '统计周期类型，格式:YYYY/YYYYQn/YYYYMM',
  `stat_cycle_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '统计周期的中文描述，如“2025年Q3”“2025年09月”',
  `region_code` char(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '符合GB/T 2260，统计区域的行政区划代码',
  `region_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '与行政区划代码关联，自动同步区域名称',
  `comp_major_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联监测部件分类配置表的大类ID',
  `comp_major_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '与部件大类ID关联，自动同步名称',
  `comp_minor_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关联监测部件分类配置表的小类ID(钻取统计时必填)',
  `comp_minor_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '与部件小类ID关联，自动同步名称',
  `total_comp_count` int NOT NULL COMMENT '该维度下监测部件总数量',
  `normal_comp_count` int NOT NULL COMMENT '状态为“正常”的部件数量',
  `abn_comp_count` int NOT NULL COMMENT '状态为“异常”的部件数量',
  `mnt_comp_count` int NOT NULL COMMENT '状态为“维护”的部件数量',
  `discard_comp_count` int NOT NULL COMMENT '状态为“废弃”的部件数量',
  `new_comp_count` int NULL DEFAULT NULL COMMENT '统计周期内新增的部件数量（创建时间在周期内）',
  `update_comp_count` int NULL DEFAULT NULL COMMENT '统计周期内更新的部件数量（更新时间在周期内）',
  `stat_user` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '生成报表的用户ID',
  `stat_time` datetime NOT NULL COMMENT '报表生成时间，格式：yyyy-MM-dd HH:mm:ss',
  `rpt_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '报表说明，如“统计范围：XX市建成区监测部件”',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预留字段，存储统计额外维度（如“统计范围”）',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预留字段，存储统计额外维度（如“统计范围”）',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预留通用字段，存储额外统计信息',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '预留通用字段，存储额外统计信息',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '监测部件统计报表' ROW_FORMAT = DYNAMIC;

