-- ----------------------------
-- Table structure for stat_mon_evt_rpt
-- ----------------------------
DROP TABLE IF EXISTS `stat_mon_evt_rpt`;
CREATE TABLE `stat_mon_evt_rpt`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '自增主键ID',
  `stat_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '唯一编码，采用UUID生成',
  `stat_cycle` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '统计周期类型，格式:“YYYY”“YYYYQn”“YYYYMM”',
  `stat_cycle_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '如“2025年09月”',
  `region_code` char(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '符合GB/T 2260，统计区域的行政区划代码',
  `region_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '与行政区划代码关联，自动同步名称',
  `evt_major_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '关联监测事件分类配置表的大类ID',
  `evt_major_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '与事件大类ID关联，自动同步名称',
  `evt_minor_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关联监测事件分类配置表的小类ID（钻取时必填）',
  `evt_minor_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '与事件小类ID关联，自动同步名称',
  `dept_code` char(18) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '事件处置部门统一社会信用代码',
  `dept_name` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '与处置部门代码关联，自动同步名称',
  `total_rpt_count` int NOT NULL COMMENT '统计周期内该维度下事件上报总数',
  `pend_count` int NOT NULL COMMENT '状态为“待处置”的事件数量',
  `handl_count` int NOT NULL COMMENT '状态为“处置中”的事件数量',
  `completed_count` int NOT NULL COMMENT '状态为“已办结”的事件数量',
  `rejected_count` int NOT NULL COMMENT '状态为“已驳回”的事件数量',
  `level1_count` int NOT NULL COMMENT '事件等级为“一级”的数量',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段1，预留',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段2，预留',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段1，预留',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段2，预留',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `complete_rate` decimal(5, 2) NOT NULL DEFAULT 0.00 COMMENT '办结率（%）',
  `avg_handle_endure` decimal(10, 2) NULL DEFAULT NULL COMMENT '平均处置时长（分钟）',
  `stat_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '报表生成时间/统计时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 23 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '监测事件统计报表' ROW_FORMAT = DYNAMIC;

