-- ----------------------------
-- Table structure for stat_mon_pt_summary_rpt
-- ----------------------------
DROP TABLE IF EXISTS `stat_mon_pt_summary_rpt`;
CREATE TABLE `stat_mon_pt_summary_rpt`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `rpt_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '报表ID',
  `stat_cycle` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '统计周期',
  `stat_cycle_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '统计周期名称',
  `admin_code` varchar(6) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '行政区划代码',
  `admin_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '行政区划名称',
  `total_pt_count` int NULL DEFAULT NULL COMMENT '点位总数量',
  `air_pt_count` int NULL DEFAULT NULL COMMENT '空气质量监测点位数',
  `traf_pt_count` int NULL DEFAULT NULL COMMENT '交通流量监测点位数',
  `manhole_pt_count` int NULL DEFAULT NULL COMMENT '井盖状态监测点位数',
  `other_pt_count` int NULL DEFAULT NULL COMMENT '其他类型点位数',
  `new_pt_count` int NULL DEFAULT NULL COMMENT '新增点位数量',
  `disable_pt_count` int NULL DEFAULT NULL COMMENT '停用点位数量',
  `pt_coverage_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '点位覆盖率',
  `rpt_create_time` datetime NULL DEFAULT NULL COMMENT '报表生成时间',
  `rpt_create_user` bigint NULL DEFAULT NULL COMMENT '报表生成人',
  `rpt_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '报表备注',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段1',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段2',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段1',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段2',
  `creator` bigint NULL DEFAULT NULL COMMENT '创建人',
  `updater` bigint NULL DEFAULT NULL COMMENT '更新人',
  `deleted` tinyint NULL DEFAULT 0 COMMENT '删除标识',
  `tenant_id` bigint NULL DEFAULT NULL COMMENT '租户ID',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '监测点位汇总报表' ROW_FORMAT = DYNAMIC;

