-- ----------------------------
-- Table structure for stat_park_oper
-- ----------------------------
DROP TABLE IF EXISTS `stat_park_oper`;
CREATE TABLE `stat_park_oper`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '[主键ID] 唯一标识每条统计记录',
  `stat_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '[统计唯一标识码] 用于唯一标识一条统计数据',
  `stat_time` datetime NOT NULL COMMENT '[统计时间] 数据统计生成时间',
  `stat_date` date NOT NULL COMMENT '[统计日期] 日统计使用，月统计为NULL',
  `stat_month` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '[统计月份] YYYY-MM，用于月统计',
  `stat_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '[统计类型] 日统计/月统计',
  `region_full_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '[行政区划编码] 12位GB/T 2260编码，仅漳州及下级区',
  `park_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '[停车场类型] 如:公共/路侧/专用',
  `entry_count` int NULL DEFAULT 0 COMMENT '[入场车次] 当日入场车辆总数',
  `exit_count` int NULL DEFAULT 0 COMMENT '[出场车次] 当日出场车辆总数',
  `total_amount` decimal(12, 2) NULL DEFAULT 0.00 COMMENT '[收费总金额] 当日收费总金额(元)',
  `avg_berth_usage` decimal(5, 2) NULL DEFAULT NULL COMMENT '[平均泊位利用率] (%)',
  `warn_count` int NULL DEFAULT 0 COMMENT '[预警总数] 当日产生的预警条数',
  `fault_device_count` int NULL DEFAULT 0 COMMENT '[故障设备数] 当日故障设备数量',
  `handled_fault_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '[故障处置率] (%) 已处理故障占总故障比例',
  `handled_warn_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '[预警处置率] (%) 已处理预警占总预警比例',
  `abnormal_flag` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '正常' COMMENT '[是否异常] 正常/异常',
  `abnormal_reason` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '[异常说明] 异常原因或描述',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '[扩展字段1] 预留字段',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '[扩展字段2] 预留字段',
  `ext_common3` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '[扩展字段3] 预留字段',
  `ext_common4` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '[扩展字段4] 预留字段',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '[创建者] 创建人账号或姓名',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '[更新者] 最后更新人账号或姓名',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '[删除标识] 0-未删除/1-已删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '[租户ID] 数据所属租户',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '[创建时间] 记录创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '[更新时间] 记录最后更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '停车运营统计表' ROW_FORMAT = DYNAMIC;

