-- ----------------------------
-- Table structure for stat_park_pay
-- ----------------------------
DROP TABLE IF EXISTS `stat_park_pay`;
CREATE TABLE `stat_park_pay`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `stat_code` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '统计记录唯一标识码',
  `stat_cycle` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '数据统计周期（如日/周/月）',
  `stat_cycle_name` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '统计周期名称，如“2025年9月”',
  `stat_start_time` datetime NULL DEFAULT NULL COMMENT '统计区间起始时间',
  `stat_end_time` datetime NULL DEFAULT NULL COMMENT '统计区间截止时间',
  `stat_time` datetime NOT NULL COMMENT '统计时间点',
  `region_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '所属区域名称',
  `region_full_code` char(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'GB/T 2260 标准12位地区码',
  `total_order_count` int NOT NULL COMMENT '统计周期内缴费总订单数',
  `total_pay_amount` decimal(18, 2) NOT NULL COMMENT '统计周期内缴费总金额',
  `pay_success_rate` decimal(5, 2) NOT NULL COMMENT '统计周期内缴费成功占比',
  `wechat_ratio` decimal(5, 2) NOT NULL COMMENT '微信支付占比',
  `alipay_ratio` decimal(5, 2) NOT NULL COMMENT '支付宝支付占比',
  `card_ratio` decimal(5, 2) NOT NULL COMMENT '银行卡支付占比',
  `region_pay_ratio` json NULL COMMENT '各区域缴费占比（数据库JSON格式）',
  `ext_cat1` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分类扩展字段1，预留',
  `ext_cat2` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '分类扩展字段2，预留',
  `ext_common1` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '通用扩展字段1，预留',
  `ext_common2` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '通用扩展字段2，预留',
  `creator` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '记录创建者',
  `updater` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '记录更新者',
  `deleted` tinyint(1) NULL DEFAULT 0 COMMENT '记录删除状态，0表示未删除',
  `tenant_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '租户唯一标识',
  `create_time` datetime NULL DEFAULT NULL COMMENT '记录创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '记录最后更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '缴费统计表' ROW_FORMAT = DYNAMIC;

