-- ----------------------------
-- Table structure for stat_scheme_sim_compare
-- ----------------------------
DROP TABLE IF EXISTS `stat_scheme_sim_compare`;
CREATE TABLE `stat_scheme_sim_compare`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `sim_compare_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '对比ID，唯一编码，UUID生成',
  `compare_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '对比名称，如“XX区域燃气方案A vs 方案B”',
  `participate_scheme_ids` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '参与方案IDs，决策方案ID，英文逗号分隔（如“id1,id2”），决策方案表（biz_decision_scheme）',
  `participate_scheme_names` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '参与方案名称，与方案IDs同步，逗号分隔，决策方案表（biz_decision_scheme）',
  `res_input_weight` int NOT NULL COMMENT '资源投入权重，%，10-50，资源投入维度权重，默认30%，权重配置表（sys_scheme_weight_cfg）',
  `expected_effect_weight` int NOT NULL COMMENT '预期效果权重，%，30-70，预期效果维度权重，默认50%，权重配置表（sys_scheme_weight_cfg）',
  `implementation_cycle_weight` int NOT NULL COMMENT '实施周期权重，%，10-30，实施周期维度权重，默认20%，权重配置表（sys_scheme_weight_cfg）',
  `scheme1_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '方案1_ID，第一个参与方案ID，决策方案表（biz_decision_scheme）',
  `scheme1_res_score` decimal(5, 2) NOT NULL COMMENT '方案1_资源投入得分，分，0-100，方案1资源投入得分（预算越低、资源利用率越高得分越高）',
  `scheme1_effect_score` decimal(5, 2) NOT NULL COMMENT '方案1_预期效果得分，分，0-100，方案1预期效果得分（事件下降率越高、响应时长越短得分越高）',
  `scheme1_cycle_score` decimal(5, 2) NOT NULL COMMENT '方案1_周期得分，分，0-100，方案1周期得分（周期越短得分越高）',
  `scheme1_composite_score` decimal(5, 2) NOT NULL COMMENT '方案1_综合得分，分，0-100，（资源得分×权重+效果得分×权重+周期得分×权重）/100',
  `scheme2_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '方案2_ID，第二个参与方案ID（至少2个方案对比），决策方案表（biz_decision_scheme）',
  `scheme2_res_score` decimal(5, 2) NOT NULL COMMENT '方案2_资源投入得分，分，0-100，同方案1逻辑',
  `scheme2_effect_score` decimal(5, 2) NOT NULL COMMENT '方案2_预期效果得分，分，0-100，同方案1逻辑',
  `scheme2_cycle_score` decimal(5, 2) NOT NULL COMMENT '方案2_周期得分，分，0-100，同方案1逻辑',
  `scheme2_composite_score` decimal(5, 2) NOT NULL COMMENT '方案2_综合得分，分，0-100，同方案1逻辑',
  `compare_conclusion` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '对比结论，如“方案1综合得分更高，推荐采纳”',
  `compare_user` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '对比人，生成对比报告的用户ID，用户信息表（sys_user）',
  `compare_time` datetime NOT NULL COMMENT '对比时间，格式：yyyy-MM-dd HH:mm:ss',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段1，预留，如“对比场景”',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段2，预留，如“对比场景”',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段1，预留，存储权重设置说明',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段2，预留，存储权重设置说明',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 20 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '方案模拟对比统计表' ROW_FORMAT = DYNAMIC;

