-- ----------------------------
-- Table structure for stat_trend_analysis_rpt
-- ----------------------------
DROP TABLE IF EXISTS `stat_trend_analysis_rpt`;
CREATE TABLE `stat_trend_analysis_rpt`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `rpt_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '报表ID',
  `trend_dim_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分析维度类型',
  `trend_dim_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分析维度ID',
  `trend_dim_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分析维度名称',
  `time_granularity` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '时间粒度',
  `start_time` date NULL DEFAULT NULL COMMENT '起始时间',
  `end_time` date NULL DEFAULT NULL COMMENT '结束时间',
  `cycle1_label` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '周期1标识',
  `cycle1_value` decimal(10, 2) NULL DEFAULT NULL COMMENT '周期1数值',
  `cycle2_label` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '周期2标识',
  `cycle2_value` decimal(10, 2) NULL DEFAULT NULL COMMENT '周期2数值',
  `overall_change_rate` decimal(5, 2) NULL DEFAULT NULL COMMENT '整体变化率',
  `trend_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '趋势类型',
  `rpt_create_time` datetime NULL DEFAULT NULL COMMENT '报表生成时间',
  `rpt_create_user` bigint NULL DEFAULT NULL COMMENT '报表生成人',
  `rpt_remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '报表备注',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段1',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段2',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段1',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段2',
  `creator` bigint NULL DEFAULT NULL COMMENT '创建人',
  `updater` bigint NULL DEFAULT NULL COMMENT '更新人',
  `deleted` tinyint NULL DEFAULT 0 COMMENT '删除标识',
  `tenant_id` bigint NULL DEFAULT NULL COMMENT '租户ID',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '综合趋势分析报表' ROW_FORMAT = DYNAMIC;

