-- ----------------------------
-- Table structure for sys_grid_cfg
-- ----------------------------
DROP TABLE IF EXISTS `sys_grid_cfg`;
CREATE TABLE `sys_grid_cfg`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID（自己编）',
  `grid_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '网格ID，UUID，作为业务唯一标识（自己编）',
  `grid_code` char(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '网格的唯一编码，用于标识城市网格',
  `grid_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '网格名称，与grid_code同步，不可手动修改',
  `grid_level` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '网格的级别，用于区分单元网格和管理网格',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_grid_id`(`grid_id` ASC) USING BTREE,
  UNIQUE INDEX `uk_grid_code`(`grid_code` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 15 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '网格配置表（sys_grid_cfg）' ROW_FORMAT = DYNAMIC;

