-- ----------------------------
-- Table structure for sys_inspection_statistics
-- ----------------------------
DROP TABLE IF EXISTS `sys_inspection_statistics`;
CREATE TABLE `sys_inspection_statistics`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `inspection_date` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '考核日期',
  `area_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '场所类型',
  `area_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '区域/地点名称',
  `total_score` decimal(5, 2) NULL DEFAULT NULL COMMENT '该场所总得分',
  `max_score` decimal(5, 2) NULL DEFAULT NULL COMMENT '该类型满分',
  `weight` decimal(5, 2) NULL DEFAULT NULL COMMENT '权重',
  `score_weighted` decimal(7, 2) NULL DEFAULT NULL COMMENT '最终得分',
  `sample_count` int NULL DEFAULT 0 COMMENT '样本数',
  `inspection_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '已完成' COMMENT '考核状态',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 1 COMMENT '租户ID',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 11 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '环卫考核统计结果表' ROW_FORMAT = DYNAMIC;

