-- ----------------------------
-- Table structure for sys_mon_evt_code_rule
-- ----------------------------
DROP TABLE IF EXISTS `sys_mon_evt_code_rule`;
CREATE TABLE `sys_mon_evt_code_rule`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `mon_evt_rule_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '规则ID，唯一编码，UUID生成',
  `rule_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '规则名称，如“监测事件18位标识码规则”',
  `admin_code_len` int NOT NULL COMMENT '行政代码位数，固定为6位，符合GB/T 2260',
  `major_code_len` int NOT NULL COMMENT '大类代码位数，固定为2位，关联事件分类表大类代码；监测事件分类配置表（sys_mon_evt_cat）',
  `mid_code_len` int NOT NULL COMMENT '中类代码位数，固定为2位，关联事件分类表中类代码；监测事件分类配置表（sys_mon_evt_cat）',
  `minor_code_len` int NOT NULL COMMENT '小类代码位数，固定为2位，关联事件分类表小类代码；监测事件分类配置表（sys_mon_evt_cat）',
  `seq_code_len` int NOT NULL COMMENT '顺序码位数，固定为6位，从000001顺序编排',
  `seq_gen_rule` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '顺序码生成规则，同一行政+小类下按上报时间递增，默认“同一县级行政区域+小类下按上报时间递增”',
  `enable_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '启用状态，同一时间仅一个规则启用，1（启用）/0（禁用）',
  `create_user` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '创建人，填写创建人账号，用户信息表(sys_user)',
  `create_time` datetime NOT NULL COMMENT '创建时间，格式：yyyy-MM-dd HH:mm:ss，系统自动生成',
  `update_user` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人，填写更新人账号，用户信息表(sys_user)',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间，格式：yyyy-MM-dd HH:mm:ss，系统自动生成',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '监测事件标识码规则表' ROW_FORMAT = DYNAMIC;

