-- ----------------------------
-- Table structure for sys_mon_evt_ext
-- ----------------------------
DROP TABLE IF EXISTS `sys_mon_evt_ext`;
CREATE TABLE `sys_mon_evt_ext`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `mon_evt_ext_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '扩展ID，唯一编码，UUID生成',
  `ext_minor_code` char(3) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '扩展小类代码，从080倒排',
  `ext_minor_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '扩展小类名称，如“智能充电桩过载事件”',
  `parent_mid_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所属中类ID，关联事件分类表中类ID；监测事件分类配置表(sys_mon_evt_cat)',
  `parent_mid_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '所属中类名称，与中类ID同步，自动填充；监测事件分类配置表(sys_mon_evt_cat)',
  `rel_comp_cat_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关联部件分类ID，关联部件分类表小类ID；监测部件分类配置表(sys_mon_comp_cat)',
  `rel_comp_cat_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '关联部件分类名称，与部件分类ID同步，自动填充；监测部件分类配置表(sys_mon_comp_cat)',
  `ext_desc` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '扩展说明，描述扩展小类用途，如“用于记录充电桩过载事件”',
  `apply_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '申请原因，说明扩展必要性，如“现有分类无法覆盖充电桩过载场景”',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '扩展监测事件配置表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of sys_mon_evt_ext
-- ----------------------------

-- ----------------------------
-- Table structure for sys_screen_template_mng
-- ----------------------------
DROP TABLE IF EXISTS `sys_screen_template_mng`;
CREATE TABLE `sys_screen_template_mng`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `screen_template_id` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板ID，唯一编码，UUID生成',
  `template_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板名称，如“城市监测事件总览大屏（2×2）”',
  `screen_layout` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '大屏布局，网格布局类型，决定组件数量及位置，取值如2×2/3×2/3×3，组件样式字典表（sys_screen_component_style）',
  `data_source_cfg` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '数据来源配置，JSON格式存储数据来源（如[{\"component_id\":\"comp1\",\"data_table\":\"stat_analysis_mon_evt\",\"idx\":\"total_rpt_count\"}]）',
  `component_cfg` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '组件配置，JSON格式存储组件配置（如[{\"component_id\":\"comp1\",\"type\":\"bar\",\"title\":\"事件上报量\",\"xField\":\"stat_cycle_name\",\"yField\":\"total_rpt_count\",\"color\":\"#1890FF\"}]），组件样式字典表（sys_screen_component_style）',
  `refresh_freq` int NOT NULL COMMENT '刷新频率，大屏数据自动刷新间隔，单位：分钟，取值范围：1-60，默认5分钟',
  `template_status` char(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板状态：启用/禁用，标识模板是否可用',
  `create_user` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '创建人，模板创建人ID，用户信息表（sys_user）',
  `create_time` datetime NOT NULL COMMENT '创建时间，格式：yyyy-MM-dd HH:mm:ss',
  `update_user` char(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '更新人，模板更新人ID，用户信息表（sys_user）',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间，格式：yyyy-MM-dd HH:mm:ss',
  `template_preview` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '模板预览图，大屏模板预览图存储路径（PNG格式）',
  `ext_cat1` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段1，预留，如“大屏用途”（指挥中心/展厅）',
  `ext_cat2` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类扩展字段2，预留，如“大屏用途”（指挥中心/展厅）',
  `ext_common1` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段1，预留，存储大屏分辨率（如“1920×1080”）',
  `ext_common2` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '通用扩展字段2，预留，存储大屏分辨率（如“1920×1080”）',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `deleted` bit(1) NULL DEFAULT b'0' COMMENT '删除标识',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户ID',
  `create_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '系统创建时间',
  `update_time_sys` datetime NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '系统更新时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '大屏模板管理表' ROW_FORMAT = DYNAMIC;

